 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Admin\Pricing\StoreCustomerGroupRequest;
 9: use App\Http\Requests\Admin\Pricing\UpdateCustomerGroupRequest;
10: use App\Http\Resources\Admin\CustomerGroupResource;
11: use App\Models\CustomerGroup;
12: use App\Services\CustomerGroupService;
13: use Illuminate\Http\JsonResponse;
14: use Illuminate\Http\Request;
15: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
16: use Illuminate\Routing\Controllers\HasMiddleware;
17: use Illuminate\Routing\Controllers\Middleware;
18: 
19: class CustomerGroupController extends Controller implements HasMiddleware
20: {
21:     public function __construct(private readonly CustomerGroupService $groups) {}
22: 
23:     public static function middleware(): array
24:     {
25:         return [
26:             new Middleware('can:customer_groups.view', only: ['index', 'show']),
27:             new Middleware('can:customer_groups.create', only: ['store']),
28:             new Middleware('can:customer_groups.update', only: ['update']),
29:             new Middleware('can:customer_groups.delete', only: ['destroy']),
30:         ];
31:     }
32: 
33:     public function index(Request $request): AnonymousResourceCollection
34:     {
35:         $filters = $request->validate([
36:             'search' => ['nullable', 'string', 'max:100'],
37:             'is_active' => ['nullable', 'boolean'],
38:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
39:         ]);
40: 
41:         return CustomerGroupResource::collection($this->groups->paginate($filters));
42:     }
43: 
44:     public function store(StoreCustomerGroupRequest $request): JsonResponse
45:     {
46:         $group = $this->groups->create($request->validated());
47: 
48:         return (new CustomerGroupResource($group))
49:             ->additional(['message' => 'تم إنشاء مجموعة العملاء بنجاح'])
50:             ->response()
51:             ->setStatusCode(201);
52:     }
53: 
54:     public function show(CustomerGroup $customerGroup): CustomerGroupResource
55:     {
56:         return new CustomerGroupResource($customerGroup->loadCount('customers'));
57:     }
58: 
59:     public function update(UpdateCustomerGroupRequest $request, CustomerGroup $customerGroup): CustomerGroupResource
60:     {
61:         return new CustomerGroupResource($this->groups->update($customerGroup, $request->validated()));
62:     }
63: 
64:     public function destroy(CustomerGroup $customerGroup): JsonResponse
65:     {
66:         $this->groups->delete($customerGroup);
67: 
68:         return response()->json(['message' => 'تم حذف مجموعة العملاء بنجاح']);
69:     }
70: }1: <?php
