 40:     protected function setUp(): void
 41:     {
 42:         parent::setUp();
 43:         $this->seed([SettingSeeder::class, InventoryPermissionSeeder::class, PricingPermissionSeeder::class]);
 44:         $this->staff = User::factory()->create();
 45:         $this->staff->givePermissionTo(Permission::where('guard_name', 'staff')->get());
 46:         $this->token = $this->staff->createToken('audit')->plainTextToken;
 47:     }
 48: 
 49:     public function test_fractional_movements_reach_exact_zero(): void
 50:     {
 51:         $variant = ProductVariant::factory()->create();
 52:         $branch = Branch::factory()->create();
 53:         $this->movement($variant, $branch, 0.3);
 54:         $this->movement($variant, $branch, -0.1);
 55:         $this->movement($variant, $branch, -0.2);
 56:         $this->assertSame('0.0000', StockLevel::firstOrFail()->on_hand);
 57:         $this->assertSame('0.0000', StockMovement::latest('id')->firstOrFail()->balance_after);
 58:     }
 59: 
 60:     public function test_inventory_and_ledger_remain_readable_after_variant_is_archived(): void
 61:     {
 62:         $variant = ProductVariant::factory()->create();
 63:         $this->movement($variant, Branch::factory()->create(), 1);
 64:         $variant->delete();
 65:         $this->api('GET', 'inventory')->assertOk()->assertJsonPath('data.0.variant.sku', $variant->sku);
 66:         $this->api('GET', 'inventory/movements')->assertOk()->assertJsonPath('data.0.variant.sku', $variant->sku);
 67:     }
 68: 
 69:     public function test_direct_ledger_update_delete_and_truncate_are_blocked_by_database(): void
 70:     {
 71:         $movement = $this->movement(ProductVariant::factory()->create(), Branch::factory()->create(), 1);
 72:         foreach (['update', 'delete', 'truncate'] as $action) {
 73:             try {
 74:                 DB::transaction(function () use ($action, $movement): void {
 75:                     match ($action) {
 76:                         'update' => DB::table('stock_movements')->where('id', $movement->id)->update(['notes' => 'tampered']),
 77:                         'delete' => DB::table('stock_movements')->where('id', $movement->id)->delete(),
 78:                         'truncate' => DB::statement('TRUNCATE stock_movements'),
 79:                     };
 80:                 });
 81:                 $this->fail('Ledger mutation must be blocked: '.$action);
 82:             } catch (QueryException $exception) {
 83:                 $this->assertStringContainsString('immutable', $exception->getMessage());
 84:             }
 85:         }
 86:         $this->assertDatabaseHas('stock_movements', ['id' => $movement->id, 'notes' => null]);
