 89:     public function test_zero_shipment_is_rejected_and_cancel_releases_all_reserved_quantity(): void
 90:     {
 91:         $variant = ProductVariant::factory()->create();
 92:         $from = Branch::factory()->create();
 93:         $to = Branch::factory()->create();
 94:         $this->movement($variant, $from, 10);
 95:         $service = app(TransferService::class);
 96:         $transfer = $service->create([
 97:             'from_branch_id' => $from->id, 'to_branch_id' => $to->id,
 98:             'items' => [['product_variant_id' => $variant->id, 'requested_qty' => 5]],
 99:         ], $this->staff->id);
100:         $service->approve($transfer, [], $this->staff->id);
