264:     private function movement(ProductVariant $variant, Branch $branch, float $qty): StockMovement
265:     {
266:         return app(InventoryService::class)->recordMovement([
267:             'product_variant_id' => $variant->id, 'branch_id' => $branch->id,
268:             'type' => $qty > 0 ? 'adjustment_in' : 'adjustment_out',
269:             'affected_bucket' => 'on_hand', 'quantity' => $qty, 'created_by' => $this->staff->id,
270:         ]);
271:     }
