240:         $stocktakeId = DB::table('stocktakes')->insertGetId([
241:             'stocktake_number' => 'STK-T1', 'branch_id' => $from->id, 'status' => 'draft',
242:             'created_by' => $this->actor->id, 'created_at' => now(), 'updated_at' => now(),
243:         ]);
244:         DB::table('stocktake_items')->insert([
245:             'stocktake_id' => $stocktakeId, 'product_variant_id' => $variant->id, 'system_qty' => 1,
246:             'created_at' => now(), 'updated_at' => now(),
247:         ]);
248:         // عدّ سالب + صنف مكرر في نفس الجلسة
249:         $this->assertThrowsQuery(fn () => DB::table('stocktake_items')->insert([
250:             'stocktake_id' => $stocktakeId, 'product_variant_id' => ProductVariant::factory()->create()->id,
251:             'system_qty' => 1, 'counted_qty' => -2, 'created_at' => now(), 'updated_at' => now(),
252:         ]));
253:         $this->assertThrowsQuery(fn () => DB::table('stocktake_items')->insert([
254:             'stocktake_id' => $stocktakeId, 'product_variant_id' => $variant->id,
255:             'system_qty' => 1, 'created_at' => now(), 'updated_at' => now(),
256:         ]));
257:     }
258: 
259:     // ---------- L2 + L5 ----------
260: 
261:     public function test_record_movement_without_creator_fails_loudly_and_reference_uses_morph_alias(): void
262:     {
263:         $branch = Branch::factory()->create();
264:         $variant = ProductVariant::factory()->create();
265: 
266:         try {
267:             app(InventoryService::class)->recordMovement([
268:                 'product_variant_id' => $variant->id, 'branch_id' => $branch->id,
269:                 'type' => StockMovementType::AdjustmentIn, 'affected_bucket' => StockBucket::OnHand, 'quantity' => 1,
270:             ]);
271:             $this->fail('missing created_by must raise LogicException');
272:         } catch (\LogicException $e) {
273:             $this->assertStringContainsString('created_by', $e->getMessage());
274:         }
275: 
276:         $staff = $this->hqStaff();
277:         $to = Branch::factory()->create();
278:         $this->movement($variant, $branch, 5);
279:         $transfer = app(TransferService::class)->create([
280:             'from_branch_id' => $branch->id, 'to_branch_id' => $to->id,
281:             'items' => [['product_variant_id' => $variant->id, 'requested_qty' => 2]],
282:         ], $staff->id);
283:         app(TransferService::class)->approve($transfer, [], $staff->id);
284:         $this->assertSame('stock_transfer', StockMovement::where('type', StockMovementType::Reserve)->firstOrFail()->reference_type);
285:     }
286: 
287:     // ---------- helpers ----------
288: 
289:     private function assertThrowsQuery(callable $fn): void
290:     {
291:         try {
292:             DB::transaction($fn); // savepoint: فشل القيد لا يسمّم معاملة الاختبار الخارجية
293:             $this->fail('expected a database constraint violation');
294:         } catch (QueryException) {
295:             $this->addToAssertionCount(1);
296:         }
297:     }
