299:     private function hqStaff(): User
300:     {
301:         return $this->staffWithPermissions([
302:             'inventory.view', 'inventory.adjust', 'inventory.all_branches', 'inventory.view_cost',
303:             'transfers.view', 'transfers.create', 'transfers.update', 'transfers.delete',
304:             'transfers.approve', 'transfers.ship', 'transfers.receive',
305:             'stocktakes.view', 'stocktakes.create', 'stocktakes.update', 'stocktakes.delete', 'stocktakes.approve',
306:             'price_lists.view', 'price_lists.create', 'price_lists.update', 'price_lists.delete',
307:             'price_lists.import', 'price_lists.export',
308:         ]);
309:     }
310: 
311:     private function staffWithPermissions(array $permissions, ?Branch $branch = null): User
312:     {
313:         foreach ($permissions as $name) {
314:             Permission::findOrCreate($name, 'staff');
315:         }
316: 
317:         $staff = User::factory()->create(['branch_id' => $branch?->id]);
318:         $staff->givePermissionTo($permissions);
319: 
320:         return $staff;
321:     }
