37:     public function index(Request $request): AnonymousResourceCollection
38:     {
39:         $filters = $request->validate([
40:             'branch_id' => ['nullable', 'integer', 'min:1'],
41:             'status' => ['nullable', Rule::in(array_column(StocktakeStatus::cases(), 'value'))],
42:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
43:         ]);
44: 
45:         $filters['staff_branch_id'] = app(BranchAccess::class)->restrictedBranch($request->user());
