 5: namespace App\Http\Resources\Admin;
 6: 
 7: use Illuminate\Http\Request;
 8: use Illuminate\Http\Resources\Json\JsonResource;
 9: 
10: class StockLevelResource extends JsonResource
11: {
12:     /**
13:      * Transform the resource into an array.
14:      *
15:      * @return array<string, mixed>
16:      */
17:     public function toArray(Request $request): array
18:     {
19:         return [
20:             'id' => $this->id,
21:             'product_variant_id' => $this->product_variant_id,
22:             'variant' => $this->whenLoaded('variant', fn () => [
23:                 'id' => $this->variant->id,
24:                 'sku' => $this->variant->sku,
25:                 'barcode' => $this->variant->barcode,
26:                 'product_id' => $this->variant->product_id,
27:                 'product_name_ar' => $this->variant->relationLoaded('product') ? $this->variant->product?->name_ar : null,
28:                 'product_name_en' => $this->variant->relationLoaded('product') ? $this->variant->product?->name_en : null,
29:             ]),
30:             'branch' => $this->whenLoaded('branch', fn () => [
31:                 'id' => $this->branch->id,
32:                 'name' => $this->branch->name,
33:             ]),
34:             'location' => $this->whenLoaded('location', fn () => $this->location ? [
35:                 'id' => $this->location->id,
36:                 'name' => $this->location->name,
37:                 'code' => $this->location->code,
38:             ] : null),
39:             'on_hand' => $this->on_hand,
40:             'reserved' => $this->reserved,
41:             'damaged' => $this->damaged,
42:             'in_transit' => $this->in_transit,
43:             'available' => number_format($this->available, 4, '.', ''),
44:             // حد إعادة الطلب الفعّال: مستوى الصف إن ضُبط (> 0)، وإلا مستوى المتغير
45:             'reorder_level' => $this->effectiveReorderLevel(),
46:             'is_low_stock' => $this->available <= $this->effectiveReorderLevel(),
47:             'updated_at' => $this->updated_at,
48:         ];
49:     }
50: 
51:     /** حد إعادة الطلب الفعّال (نفس صيغة فلتر low_stock في الكنترولر). */
52:     private function effectiveReorderLevel(): float
53:     {
54:         if ((float) $this->reorder_level > 0) {
55:             return (float) $this->reorder_level;
56:         }
57: 
58:         return $this->relationLoaded('variant') ? (float) ($this->variant?->reorder_level ?? 0) : 0.0;
59:     }
60: } 1: <?php
