 5: namespace App\Models;
 6: 
 7: use App\Enums\StockBucket;
 8: use App\Enums\StockMovementType;
 9: use Illuminate\Database\Eloquent\Model;
10: use Illuminate\Database\Eloquent\Relations\BelongsTo;
11: use Illuminate\Database\Eloquent\Relations\MorphTo;
12: use LogicException;
13: 
14: /**
15:  * سجل دفتر أستاذ المخزون: تاريخي وغير قابل للتعديل أو الحذف نهائيًا (Immutable Ledger).
16:  */
17: class StockMovement extends Model
18: {
19:     /** لا يوجد updated_at: السجل لا يتغير بعد كتابته. */
20:     public const UPDATED_AT = null;
21: 
22:     protected $fillable = [
23:         'reference_number', 'product_variant_id', 'branch_id', 'location_id',
24:         'type', 'affected_bucket', 'quantity', 'balance_before', 'balance_after',
25:         'unit_cost', 'reference_type', 'reference_id', 'created_by', 'notes',
26:     ];
27: 
28:     protected $casts = [
29:         'type' => StockMovementType::class,
30:         'affected_bucket' => StockBucket::class,
31:         'quantity' => 'decimal:4',
32:         'balance_before' => 'decimal:4',
33:         'balance_after' => 'decimal:4',
34:         'unit_cost' => 'decimal:4',
35:     ];
36: 
37:     protected static function booted(): void
38:     {
39:         static::updating(fn () => throw new LogicException('سجلات دفتر المخزون لا تُعدَّل'));
40:         static::deleting(fn () => throw new LogicException('سجلات دفتر المخزون لا تُحذف'));
41:     }
42: 
43:     public function variant(): BelongsTo
44:     {
45:         return $this->belongsTo(ProductVariant::class, 'product_variant_id')->withTrashed();
46:     }
47: 
48:     public function branch(): BelongsTo
49:     {
50:         return $this->belongsTo(Branch::class);
51:     }
52: 
53:     public function location(): BelongsTo
54:     {
55:         return $this->belongsTo(Location::class);
56:     }
57: 
58:     public function creator(): BelongsTo
59:     {
60:         return $this->belongsTo(User::class, 'created_by');
61:     }
62: 
63:     public function reference(): MorphTo
64:     {
65:         return $this->morphTo();
66:     }
67: } 1: <?php
