 22: class InventoryConcurrencyTest extends TestCase
 23: {
 24:     use DatabaseMigrations;
 25: 
 26:     private User $staff;
 27: 
 28:     protected function setUp(): void
 29:     {
 30:         parent::setUp();
 31:         $this->seed(SettingSeeder::class);
 32:         // مشغّل مركز رئيسي: بلا فرع لكن بامتياز صريح لكل الفروع (fail-closed خلاف ذلك)
 33:         $this->staff = User::factory()->create();
 34:         $this->staff->givePermissionTo(Permission::findOrCreate('inventory.all_branches', 'staff'));
 35:     }
 36: 
 37:     protected function tearDown(): void
 38:     {
 39:         // Workers commit real ledger entries. Discard test fixtures before rolling back enum migrations.
 40:         $this->artisan('migrate:fresh', ['--force' => true]);
 41:         parent::tearDown();
 42:     }
 43: 
 44:     public function test_first_movements_create_exactly_one_stock_row_under_concurrency(): void
 45:     {
 46:         $variant = ProductVariant::factory()->create();
 47:         $branch = Branch::factory()->create();
 48:         $data = $this->data($variant, $branch);
 49:         $operation = 'app(App\Services\InventoryService::class)->recordMovement('.var_export($data, true).');';
 50:         $this->race([$operation, $operation]);
 51:         $this->assertSame(1, StockLevel::count());
 52:         $this->assertSame('2.0000', StockLevel::firstOrFail()->on_hand);
 53:         $this->assertSame(2, StockMovement::distinct()->count('reference_number'));
 54:     }
 55: 
 56:     public function test_opposite_multi_item_orders_do_not_deadlock(): void
 57:     {
 58:         $variants = ProductVariant::factory()->count(2)->create();
 59:         $branch = Branch::factory()->create();
 60:         $items = $variants->map(fn ($variant) => ['product_variant_id' => $variant->id, 'quantity' => 1, 'adjustment_type' => 'increase'])->all();
 61:         $jobs = [];
 62:         foreach ([$items, array_reverse($items)] as $order) {
 63:             $jobs[] = 'app(App\Services\InventoryService::class)->applyAdjustments('.var_export(['branch_id' => $branch->id, 'items' => $order], true).', '.$this->staff->id.');';
 64:         }
 65:         $this->race($jobs);
 66:         $this->assertSame(['2.0000', '2.0000'], StockLevel::orderBy('product_variant_id')->pluck('on_hand')->all());
 67:     }
 68: 
 69:     public function test_unrelated_movements_can_reach_ledger_insert_at_the_same_time(): void
 70:     {
 71:         $jobs = [];
 72:         foreach (['left' => 'right', 'right' => 'left'] as $own => $other) {
 73:             $data = $this->data(ProductVariant::factory()->create(), Branch::factory()->create());
 74:             $hook = 'App\Models\StockMovement::creating(function () { $prefix = getenv("INVENTORY_START_FILE"); touch($prefix.'.var_export('.'.$own, true).'); $deadline = microtime(true) + 5; while (!is_file($prefix.'.var_export('.'.$other, true).')) { if (microtime(true) > $deadline) { throw new RuntimeException("Movement numbering serialized unrelated stock rows"); } usleep(10000); } });';
 75:             $jobs[] = $hook.'app(App\Services\InventoryService::class)->recordMovement('.var_export($data, true).');';
 76:         }
 77:         $this->race($jobs);
 78:         $this->assertSame(2, StockMovement::count());
 79:     }
 80: 
 81:     public function test_opposing_shipments_lock_both_branches_in_the_same_order(): void
 82:     {
 83:         $from = Branch::factory()->create();
 84:         $to = Branch::factory()->create();
 85:         $variant = ProductVariant::factory()->create();
 86:         foreach ([$from, $to] as $branch) {
 87:             app(InventoryService::class)->recordMovement([...$this->data($variant, $branch), 'quantity' => 10]);
 88:         }
 89:         $jobs = [];
 90:         foreach ([[$from, $to], [$to, $from]] as [$source, $destination]) {
 91:             $transfer = app(TransferService::class)->create(['from_branch_id' => $source->id, 'to_branch_id' => $destination->id,
 92:                 'items' => [['product_variant_id' => $variant->id, 'requested_qty' => 2]],
 93:             ], $this->staff->id);
 94:             app(TransferService::class)->approve($transfer, [], $this->staff->id);
 95:             $jobs[] = 'app(App\Services\TransferService::class)->ship(App\Models\StockTransfer::findOrFail('.$transfer->id.'), [], '.$this->staff->id.');';
 96:         }
 97:         $this->race($jobs);
 98:         foreach (StockLevel::all() as $stock) {
 99:             $this->assertSame('8.0000', $stock->on_hand);
100:             $this->assertSame('0.0000', $stock->reserved);
101:             $this->assertSame('2.0000', $stock->in_transit);
102:         }
103:     }
104: 
105:     public function test_concurrent_stocktakes_cannot_double_apply_the_same_difference(): void
106:     {
107:         $branch = Branch::factory()->create();
108:         $variant = ProductVariant::factory()->create();
109:         app(InventoryService::class)->recordMovement([...$this->data($variant, $branch), 'quantity' => 10]);
110:         $jobs = [];
111:         foreach ([1, 2] as $iteration) {
112:             $stocktake = app(StocktakeService::class)->create(['branch_id' => $branch->id,
113:                 'items' => [['product_variant_id' => $variant->id, 'counted_qty' => 7]],
114:             ], $this->staff->id);
115:             $jobs[] = 'app(App\Services\StocktakeService::class)->approve(App\Models\Stocktake::findOrFail('.$stocktake->id.'), '.$this->staff->id.');';
116:         }
117:         $this->race($jobs, ['OK', 'REJECTED']);
118:         $this->assertSame('7.0000', StockLevel::firstOrFail()->on_hand);
119:         $this->assertSame(1, StockMovement::where('type', 'stocktake_loss')->count());
120:     }
