122:     public function test_concurrent_duplicate_price_tiers_have_a_business_error(): void
123:     {
124:         $variant = ProductVariant::factory()->create();
125:         $list = PriceList::create(['name' => 'Retail', 'type' => 'retail']);
126:         $operation = 'app(App\Services\PriceListService::class)->createItem(App\Models\PriceList::findOrFail('.$list->id.'), '.var_export(['product_variant_id' => $variant->id, 'min_qty' => 1, 'price' => 10], true).');';
127:         $this->race([$operation, $operation], ['OK', 'REJECTED']);
128:         $this->assertSame(1, $list->items()->count());
129:     }
