131:     private function data(ProductVariant $variant, Branch $branch): array
132:     {
133:         return ['product_variant_id' => $variant->id, 'branch_id' => $branch->id,
134:             'type' => 'adjustment_in', 'affected_bucket' => 'on_hand', 'quantity' => 1, 'created_by' => $this->staff->id];
135:     }
136: 
137:     private function race(array $jobs, array $expected = ['OK', 'OK']): void
138:     {
139:         $barrier = tempnam(sys_get_temp_dir(), 'inventory-race-');
140:         unlink($barrier);
141:         $db = config('database.connections.pgsql');
142:         $environment = ['APP_ENV' => 'testing', 'DB_CONNECTION' => 'pgsql', 'DB_DATABASE' => $db['database'],
143:             'DB_HOST' => $db['host'], 'DB_PORT' => (string) $db['port'], 'DB_USERNAME' => $db['username'],
144:             'DB_PASSWORD' => $db['password'], 'DB_URL' => '', 'CACHE_STORE' => 'array', 'QUEUE_CONNECTION' => 'sync',
145:             'INVENTORY_START_FILE' => $barrier];
146:         $processes = [];
147:         try {
148:             foreach ($jobs as $operation) {
149:                 $script = <<<'PHP'
150: require 'vendor/autoload.php';
151: $app = require 'bootstrap/app.php';
152: $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
153: Illuminate\Support\Facades\DB::statement("SET lock_timeout = '7s'");
154: echo "READY\n";
155: $deadline = microtime(true) + 12;
156: while (!is_file(getenv('INVENTORY_START_FILE'))) {
157:     if (microtime(true) > $deadline) { exit(4); }
158:     usleep(10000);
159: }
160: try {
161: PHP;
162:                 $script .= $operation;
163:                 $script .= <<<'PHP'
164: echo "OK\n";
165: } catch (App\Exceptions\BusinessException $exception) {
166:     echo "REJECTED\n";
167: } catch (Throwable $exception) {
168:     fwrite(STDERR, get_class($exception).': '.$exception->getMessage());
169:     exit(3);
170: }
171: PHP;
172:                 $process = new Process([PHP_BINARY, '-r', $script], base_path(), $environment, timeout: 15);
173:                 $process->start();
174:                 $processes[] = $process;
175:             }
176:             foreach ($processes as $process) {
177:                 $this->assertTrue($process->waitUntil(fn ($type, $output) => str_contains($output, 'READY')), $process->getErrorOutput());
178:             }
179:             touch($barrier);
180:             $results = [];
181:             foreach ($processes as $process) {
182:                 $process->wait();
183:                 $this->assertTrue($process->isSuccessful(), $process->getErrorOutput());
184:                 $results[] = trim(str_replace('READY', '', $process->getOutput()));
185:             }
186:             $this->assertEqualsCanonicalizing($expected, $results);
187:         } finally {
188:             foreach ($processes as $process) {
189:                 if ($process->isRunning()) {
190:                     $process->stop();
191:                 }
192:             }
193:             foreach ([$barrier, $barrier.'.left', $barrier.'.right'] as $path) {
194:                 if (is_file($path)) {
195:                     unlink($path);
196:                 }
197:             }
198:         }
199:     }
200: }  1: <?php
