 62:     public function test_resaving_a_stocktake_does_not_refresh_snapshots_or_hide_sales(): void
 63:     {
 64:         $staff = $this->staffWithPermissions(self::ALL_PERMISSIONS);
 65:         $branch = Branch::factory()->create();
 66:         $variant = ProductVariant::factory()->create();
 67:         $this->movement($variant, $branch, 10);
 68: 
 69:         $service = app(StocktakeService::class);
 70:         $stocktake = $service->create(['branch_id' => $branch->id, 'items' => [
 71:             ['product_variant_id' => $variant->id, 'counted_qty' => 10],
 72:         ]], $staff->id);
 73: 
 74:         // بيع قطعتين بعد العد
 75:         $this->movement($variant, $branch, -2, StockMovementType::AdjustmentOut);
 76: 
 77:         // إعادة حفظ بنفس الأعداد (الواجهة ترسل المصفوفة كاملة) — لا يجوز أن تجدد اللقطة
 78:         $service->update($stocktake, ['items' => [
 79:             ['product_variant_id' => $variant->id, 'counted_qty' => 10],
 80:         ]], $staff->id);
 81:         $this->assertSame('10.0000', $stocktake->items()->firstOrFail()->system_qty);
 82: 
 83:         // الاعتماد يرفض ويرجع قائمة الأصناف المحتاجة إعادة عد، ولا يصنع فائضًا وهميًا
 84:         try {
 85:             $service->approve($stocktake, $staff->id);
 86:             $this->fail('approve must reject a stale count');
 87:         } catch (BusinessException $e) {
 88:             $this->assertSame([$variant->id], $e->errors['recount_variant_ids']);
 89:         }
 90:         $this->assertSame('8.0000', StockLevel::where('product_variant_id', $variant->id)->firstOrFail()->on_hand);
 91:         $this->assertSame(0, StockMovement::where('type', StockMovementType::StocktakeGain)->count());
 92:     }
