136:     // ---------- H2: التسويات لا تتكرر مع Idempotency-Key ----------
137: 
138:     public function test_adjustments_with_idempotency_key_apply_once(): void
139:     {
140:         $staff = $this->staffWithPermissions(self::ALL_PERMISSIONS);
141:         $token = $staff->createToken('test')->plainTextToken;
142:         $branch = Branch::factory()->create();
143:         $variant = ProductVariant::factory()->create();
144:         $payload = ['branch_id' => $branch->id, 'items' => [
145:             ['product_variant_id' => $variant->id, 'adjustment_type' => 'increase', 'quantity' => 5],
146:         ]];
147: 
148:         $first = $this->requestWithToken($token, 'POST', '/api/v1/admin/inventory/adjustments', $payload, ['Idempotency-Key' => 'pos-retry-001'])->assertCreated();
149:         $firstIds = collect($first->json('data'))->pluck('id')->all();
150:         $movementsAfterFirst = StockMovement::count();
151: 
152:         // إعادة الإرسال (retry): نفس الرد، بلا حركات جديدة، والرصيد لا يتضاعف
153:         $replay = $this->requestWithToken($token, 'POST', '/api/v1/admin/inventory/adjustments', $payload, ['Idempotency-Key' => 'pos-retry-001'])->assertCreated();
154:         $this->assertSame($firstIds, collect($replay->json('data'))->pluck('id')->all());
155:         $this->assertSame($movementsAfterFirst, StockMovement::count());
156:         $this->assertSame('5.0000', StockLevel::where('product_variant_id', $variant->id)->firstOrFail()->on_hand);
157: 
158:         // نفس المفتاح بحمولة مختلفة: 409
159:         $changed = $payload;
160:         $changed['items'][0]['quantity'] = 7;
161:         $this->requestWithToken($token, 'POST', '/api/v1/admin/inventory/adjustments', $changed, ['Idempotency-Key' => 'pos-retry-001'])
162:             ->assertStatus(409);
163:         $this->assertSame('5.0000', StockLevel::where('product_variant_id', $variant->id)->firstOrFail()->on_hand);
164:     }
