201:     public function test_approve_rejects_item_ids_that_no_longer_belong_to_the_transfer(): void
202:     {
203:         $staff = $this->staffWithPermissions(self::ALL_PERMISSIONS);
204:         $from = Branch::factory()->create();
205:         $to = Branch::factory()->create();
206:         $variant = ProductVariant::factory()->create();
207:         $this->movement($variant, $from, 10);
208: 
209:         $transfers = app(TransferService::class);
210:         $transfer = $transfers->create([
211:             'from_branch_id' => $from->id, 'to_branch_id' => $to->id,
212:             'items' => [['product_variant_id' => $variant->id, 'requested_qty' => 4]],
213:         ], $staff->id);
214:         $staleItemId = $transfer->items->firstOrFail()->id;
215: 
216:         // المُنشئ يعدّل المسودة: معرّفات جديدة تمامًا
217:         $transfers->update($transfer, ['items' => [
218:             ['product_variant_id' => $variant->id, 'requested_qty' => 6],
219:         ]], $staff->id);
220: 
221:         // المعتمد بحمولة قديمة: رفض 409 بدل تجاهل المعرّفات بصمت واعتماد ما لم يره
222:         try {
223:             $transfers->approve($transfer, [$staleItemId => 4], $staff->id);
224:             $this->fail('stale item ids must be rejected');
225:         } catch (BusinessException $e) {
226:             $this->assertSame(409, $e->status);
227:             $this->assertSame([$staleItemId], $e->errors['unknown_item_ids']);
228:         }
229:         $this->assertSame('draft', $transfer->fresh()->status->value);
230:         $this->assertSame(0, StockMovement::where('type', StockMovementType::Reserve)->count());
231:     }
