285:     private function staffWithPermissions(array $permissions): User
286:     {
287:         foreach ($permissions as $name) {
288:             Permission::findOrCreate($name, 'staff');
289:         }
290: 
291:         $staff = User::factory()->create();
292:         $staff->givePermissionTo($permissions);
293: 
294:         return $staff;
295:     }
296: 
297:     private function requestWithToken(string $token, string $method, string $uri, array $data = [], array $headers = []): TestResponse
298:     {
299:         Auth::forgetGuards();
300: 
301:         return $this->withToken($token)->withHeaders($headers)->json($method, $uri, $data);
302:     }
303: 
304:     private function movement(ProductVariant $variant, Branch $branch, float $qty, StockMovementType $type = StockMovementType::AdjustmentIn): void
305:     {
306:         app(InventoryService::class)->recordMovement([
307:             'product_variant_id' => $variant->id, 'branch_id' => $branch->id,
308:             'type' => $type, 'affected_bucket' => StockBucket::OnHand, 'quantity' => $qty,
309:             'created_by' => $this->actor->id,
310:         ]);
311:     }
312: 
313:     private function customer(CustomerType $type, ?int $groupId = null): Customer
314:     {
315:         return Customer::create([
316:             'name' => 'Buyer', 'email' => uniqid().'@example.com', 'phone' => uniqid(),
317:             'password' => 'password', 'type' => $type, 'status' => CustomerStatus::Approved,
318:             'customer_group_id' => $groupId,
319:         ]);
320:     }
