 5: namespace App\Http\Requests\Admin\Transfer;
 6: 
 7: use Illuminate\Foundation\Http\FormRequest;
 8: use Illuminate\Validation\Rule;
 9: 
10: /**
11:  * طلبات مراحل التحويل (اعتماد/شحن/استلام): كميات اختيارية لكل عنصر،
12:  * وغياب عنصر يعني استخدام الكمية الافتراضية للمرحلة السابقة.
13:  */
14: class TransferItemsQtyRequest extends FormRequest
15: {
16:     public function authorize(): bool
17:     {
18:         return true;
19:     }
20: 
21:     /** حقل الكمية الخاص بالمرحلة الحالية — بيتحدد في الكلاس الفرعي. */
22:     protected string $qtyField = 'approved_qty';
23: 
24:     /**
25:      * @return array<string, mixed>
26:      */
27:     public function rules(): array
28:     {
29:         $transferId = $this->route('transfer')?->id;
30: 
31:         return [
32:             'expected_updated_at' => ['nullable', 'date'],
33:             'items' => ['nullable', 'array', 'max:100'],
34:             'items.*.id' => [
35:                 'required', 'bail', 'integer', 'min:1', 'distinct',
36:                 Rule::exists('stock_transfer_items', 'id')->where('stock_transfer_id', $transferId),
37:             ],
38:             "items.*.{$this->qtyField}" => ['required', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
39:         ];
40:     }
41: 
42:     /**
43:      * خريطة [معرّف العنصر => الكمية] جاهزة للخدمة.
44:      *
45:      * @return array<int, float>
46:      */
47:     public function quantitiesByItemId(): array
48:     {
49:         $map = [];
50: 
51:         foreach ($this->validated('items', []) ?? [] as $item) {
52:             $map[(int) $item['id']] = (float) $item[$this->qtyField];
53:         }
54: 
55:         return $map;
56:     }
57: } 1: <?php
