11: class UpdateSettingsRequest extends FormRequest
12: {
13:     public function authorize(): bool
14:     {
15:         return $this->user() !== null;
16:     }
17: 
18:     /** @return array<string, mixed> */
19:     public function validationData(): array
20:     {
21:         return $this->isJson() ? $this->json()->all() : $this->request->all();
22:     }
23: 
24:     /**
25:      * @return array<string, array<mixed>|string|ValidationRule>
26:      */
27:     public function rules(): array
28:     {
29:         return [
30:             'company_name' => ['sometimes', 'nullable', 'string', 'max:255'],
31:             'company_email' => ['sometimes', 'nullable', 'email', 'max:255'],
32:             'company_phone' => ['sometimes', 'nullable', 'string', 'max:50'],
33:             'company_address' => ['sometimes', 'nullable', 'string', 'max:1000'],
34:             'company_logo' => ['sometimes', 'nullable', 'string', 'max:2048'],
35:             'commercial_register' => ['sometimes', 'nullable', 'string', 'max:100'],
36: 
37:             'tax_enabled' => ['sometimes', 'boolean'],
38:             'tax_number' => ['sometimes', 'nullable', 'string', 'max:100'],
39:             'default_tax_rate' => ['sometimes', 'numeric', 'between:0,100'],
40:             'prices_include_tax' => ['sometimes', 'boolean'],
41: 
42:             'invoice_prefix' => ['sometimes', 'nullable', 'string', 'max:30'],
43:             'invoice_next_number' => ['sometimes', 'integer', 'min:1'],
44:             'invoice_padding' => ['sometimes', 'integer', 'min:1', 'max:20'],
45:             'order_prefix' => ['sometimes', 'nullable', 'string', 'max:30'],
46:             'order_next_number' => ['sometimes', 'integer', 'min:1'],
47:             'order_padding' => ['sometimes', 'integer', 'min:1', 'max:20'],
48:             'purchase_order_prefix' => ['sometimes', 'nullable', 'string', 'max:30'],
49:             'purchase_order_next_number' => ['sometimes', 'integer', 'min:1'],
50:             'purchase_order_padding' => ['sometimes', 'integer', 'min:1', 'max:20'],
51:             'quotation_prefix' => ['sometimes', 'nullable', 'string', 'max:30'],
52:             'quotation_next_number' => ['sometimes', 'integer', 'min:1'],
53:             'quotation_padding' => ['sometimes', 'integer', 'min:1', 'max:20'],
54:         ];
55:     }
56: 
57:     public function withValidator(Validator $validator): void
58:     {
59:         $allowedKeys = array_keys($this->rules());
60:         $body = $this->validationData();
61:         $unknownKeys = array_diff(array_keys($body), $allowedKeys, ['_method', '_token']);
62: 
63:         $validator->after(function (Validator $validator) use ($unknownKeys): void {
64:             foreach ($unknownKeys as $unknownKey) {
65:                 $validator->errors()->add($unknownKey, 'إعداد غير معروف.');
66:             }
67:         });
68:     }
