  7: use App\Enums\PriceListType;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\PriceList;
 10: use App\Models\PriceListItem;
 11: use App\Models\ProductVariant;
 12: use App\Models\User;
 13: use Carbon\Carbon;
 14: use DateTimeInterface;
 15: use Illuminate\Auth\Access\AuthorizationException;
 16: use Illuminate\Contracts\Pagination\LengthAwarePaginator;
 17: use Illuminate\Http\UploadedFile;
 18: use Illuminate\Support\Facades\DB;
 19: use Illuminate\Support\Facades\Validator;
 20: use Symfony\Component\HttpFoundation\StreamedResponse;
 21: 
 22: /**
 23:  * إدارة قوائم الأسعار وعناصرها واستيراد/تصدير CSV.
 24:  * منطق حساب السعر نفسه في PricingService.
 25:  */
 26: class PriceListService
 27: {
 28:     public function paginate(array $filters, ?User $user = null): LengthAwarePaginator
 29:     {
 30:         return PriceList::query()
 31:             ->with(['customer', 'customerGroup', 'branch'])
 32:             ->withCount('items')
 33:             ->when($this->restrictedBranch($user) !== null, fn ($q) => $q->where('branch_id', $this->restrictedBranch($user)))
 34:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 35:             ->when($filters['customer_id'] ?? null, fn ($q, $v) => $q->where('customer_id', $v))
 36:             ->when($filters['customer_group_id'] ?? null, fn ($q, $v) => $q->where('customer_group_id', $v))
 37:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 38:             ->when(array_key_exists('is_active', $filters) && $filters['is_active'] !== null, fn ($q) => $q->where('is_active', $filters['is_active']))
 39:             ->when($filters['search'] ?? null, fn ($q, $v) => $q->whereLike('name', '%'.SearchTerm::escape($v).'%', caseSensitive: false))
 40:             ->orderByDesc('priority')
 41:             ->orderByDesc('id')
 42:             ->paginate($filters['per_page'] ?? 15);
 43:     }
 44: 
 45:     public function find(int $id, ?User $user = null): PriceList
 46:     {
 47:         return PriceList::query()
 48:             ->with(['customer', 'customerGroup', 'branch'])
 49:             ->withCount('items')
 50:             ->when($this->restrictedBranch($user) !== null, fn ($q) => $q->where('branch_id', $this->restrictedBranch($user)))
 51:             ->findOrFail($id);
 52:     }
 53: 
 54:     public function create(array $data, ?User $user = null): PriceList
 55:     {
 56:         $restricted = $this->restrictedBranch($user);
 57:         if ($restricted !== null) {
 58:             if (isset($data['branch_id']) && (int) $data['branch_id'] !== $restricted) {
 59:                 throw new AuthorizationException('لا تملك صلاحية إنشاء قوائم أسعار لفرع آخر.');
 60:             }
 61:             $data['branch_id'] = $restricted;
 62:         }
 63:         $data = $this->normalizeDates($data);
 64:         $data = array_filter($data, fn ($value, $key) => $value !== null || ! in_array($key, ['currency', 'priority', 'is_active'], true), ARRAY_FILTER_USE_BOTH);
 65:         $this->validateDates($data);
 66:         $data = $this->withValidOwner($data);
 67: 
 68:         return PriceList::query()->create($data)->load(['customer', 'customerGroup', 'branch']);
 69:     }
 70: 
 71:     public function update(PriceList $priceList, array $data, ?User $user = null): PriceList
 72:     {
 73:         $this->assertListAccess($user, $priceList);
 74:         if ($this->restrictedBranch($user) !== null && isset($data['branch_id']) && (int) $data['branch_id'] !== $this->restrictedBranch($user)) {
 75:             throw new AuthorizationException('لا تملك صلاحية نقل قائمة أسعار إلى فرع آخر.');
 76:         }
 77:         $data = $this->normalizeDates($data);
 78: 
 79:         return DB::transaction(function () use ($priceList, $data): PriceList {
 80:             $priceList = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
 81:             $this->validateDates($data, $priceList);
 82:             $data = $this->withValidOwner($data, $priceList);
 83:             $priceList->update($data);
 84: 
 85:             return $priceList->load(['customer', 'customerGroup', 'branch']);
 86:         });
 87:     }
 88: 
 89:     private function withValidOwner(array $data, ?PriceList $priceList = null): array
 90:     {
 91:         // فرض ربط النوع بالمالك على الحالة النهائية: النوع الخاص بعميل لازم له عميل،
 92:         // والخاص بمجموعة لازم له مجموعة، وأي نوع تاني بيصفّي الحقلين تلقائيًا
 93:         $type = $data['type'] ?? $priceList?->type;
 94:         $typeValue = $type instanceof PriceListType ? $type->value : $type;
 95: 
 96:         if ($typeValue === PriceListType::CustomerSpecific->value) {
 97:             $customerId = array_key_exists('customer_id', $data) ? $data['customer_id'] : $priceList?->customer_id;
 98:             if ($customerId === null) {
 99:                 throw new BusinessException('قائمة الأسعار الخاصة بعميل تتطلب تحديد العميل.');
100:             }
101:             $data['customer_id'] = $customerId;
102:             $data['customer_group_id'] = null;
103:         } elseif ($typeValue === PriceListType::CustomerGroup->value) {
104:             $groupId = array_key_exists('customer_group_id', $data) ? $data['customer_group_id'] : $priceList?->customer_group_id;
105:             if ($groupId === null) {
106:                 throw new BusinessException('قائمة أسعار المجموعة تتطلب تحديد مجموعة العملاء.');
107:             }
108:             $data['customer_group_id'] = $groupId;
109:             $data['customer_id'] = null;
110:         } else {
111:             $data['customer_id'] = null;
112:             $data['customer_group_id'] = null;
113:         }
114: 
115:         return $data;
116:     }
117: 
118:     public function delete(PriceList $priceList, ?User $user = null): void
119:     {
120:         $this->assertListAccess($user, $priceList);
121:         $priceList->delete(); // العناصر بتتحذف بـ cascade في القاعدة
122:     }
123: 
124:     // ---------- Items ----------
125: 
126:     public function paginateItems(PriceList $priceList, array $filters, ?User $user = null): LengthAwarePaginator
127:     {
128:         $this->assertListAccess($user, $priceList);
129: 
130:         return $priceList->items()
131:             ->with(['variant.product'])
132:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
133:             ->orderBy('product_variant_id')
134:             ->orderBy('min_qty')
135:             ->orderBy('id')
136:             ->paginate($filters['per_page'] ?? 15);
137:     }
138: 
139:     public function createItem(PriceList $priceList, array $data, ?User $user = null): PriceListItem
140:     {
141:         $this->assertListAccess($user, $priceList);
142:         $data = $this->normalizeDates($data);
143: 
144:         return DB::transaction(function () use ($priceList, $data): PriceListItem {
145:             $priceList = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
146:             $data['min_qty'] = $data['min_qty'] ?? 1;
147:             $this->validateDates($data);
148:             $this->assertNoDuplicateTier($priceList, (int) $data['product_variant_id'], (float) $data['min_qty']);
149: 
150:             return $priceList->items()->create($data)->load('variant.product');
151:         });
152:     }
153: 
154:     public function updateItem(PriceListItem $item, array $data, ?User $user = null): PriceListItem
155:     {
156:         $this->assertListAccess($user, $item->priceList);
157:         $data = $this->normalizeDates($data);
158: 
159:         return DB::transaction(function () use ($item, $data): PriceListItem {
160:             PriceList::query()->lockForUpdate()->findOrFail($item->price_list_id);
161:             $item = PriceListItem::query()->lockForUpdate()->findOrFail($item->id);
162:             $this->validateDates($data, $item);
163:             if (isset($data['product_variant_id']) || isset($data['min_qty'])) {
164:                 $this->assertNoDuplicateTier(
165:                     $item->priceList,
166:                     (int) ($data['product_variant_id'] ?? $item->product_variant_id),
