199:     /** تصدير عناصر القائمة كـ CSV بنفس أعمدة الاستيراد عشان إعادة الاستيراد تشتغل. */
200:     public function exportCsv(PriceList $priceList, ?User $user = null): StreamedResponse
201:     {
202:         $this->assertListAccess($user, $priceList);
203: 
204:         return response()->streamDownload(function () use ($priceList): void {
205:             $handle = fopen('php://output', 'w');
206:             try {
207:                 fputcsv($handle, ['sku', 'variant_id', 'product_name', 'min_qty', 'price', 'starts_at', 'ends_at']);
208: 
209:                 $priceList->items()
210:                     ->with(['variant.product' => fn ($query) => $query->withTrashed()])
211:                     ->chunkById(500, function ($items) use ($handle): void {
212:                         foreach ($items as $item) {
213:                             fputcsv($handle, [
214:                                 $this->csvText($item->variant?->sku ?? ''),
215:                                 $item->product_variant_id,
216:                                 $this->csvText($item->variant?->product?->name_ar ?? ''),
217:                                 $item->min_qty,
218:                                 $item->price,
219:                                 $item->starts_at?->toIso8601String(),
220:                                 $item->ends_at?->toIso8601String(),
221:                             ]);
222:                         }
223:                     });
224: 
225:             } finally {
226:                 fclose($handle);
227:             }
228:         }, 'price-list-'.$priceList->id.'.csv', ['Content-Type' => 'text/csv; charset=UTF-8']);
229:     }
