231:     private function csvText(string $value): string
232:     {
233:         return preg_match('/^[\s]*[=+@\-\t\r\n]/u', $value) ? "'".$value : $value;
234:     }
235: 
236:     /**
237:      * استيراد CSV: كل صف بيحدّث أو ينشئ عنصرًا بمفتاح (القائمة، المتغير، min_qty)
238:      * داخل transaction واحدة. أخطاء الصفوف الفردية بتتجمع في التقرير من غير ما توقف الكل.
239:      *
240:      * @return array{created: int, updated: int, skipped: int, errors: list<array{line: int, message: string}>}
241:      */
242:     public function importCsv(PriceList $priceList, UploadedFile $file, ?User $user = null): array
243:     {
244:         $this->assertListAccess($user, $priceList);
245:         $handle = fopen($file->getRealPath(), 'r');
246:         if ($handle === false) {
247:             throw new BusinessException('تعذرت قراءة ملف الاستيراد.');
248:         }
249:         try {
250:             $header = fgetcsv($handle);
251:             if ($header === false) {
252:                 throw new BusinessException('ملف الاستيراد فارغ.');
253:             }
254:             $header[0] = preg_replace('/^\xEF\xBB\xBF/', '', (string) $header[0]);
255:             $columns = array_map(fn ($h) => strtolower(trim((string) $h)), $header);
256:             $index = array_flip($columns);
257:             if (count($index) !== count($columns) || ! isset($index['price']) || (! isset($index['variant_id']) && ! isset($index['sku']))) {
258:                 throw new BusinessException('يجب أن يحتوي الملف على price وsku أو variant_id، دون أعمدة مكررة.');
259:             }
260:             $rows = [];
261:             $line = 1;
262:             while (($row = fgetcsv($handle)) !== false) {
263:                 $line++;
264:                 if ($line > 10000) {
265:                     throw new BusinessException('عدد أسطر الملف يتجاوز الحد المسموح.');
266:                 }
267:                 if ($row === [null] || trim(implode('', array_map('strval', $row))) === '') {
268:                     continue;
269:                 }
270:                 if (count($rows) >= 2000) {
271:                     throw new BusinessException('الحد الأقصى للاستيراد المتزامن 2000 صف؛ قسّم الملف إلى أجزاء أصغر.');
272:                 }
273:                 $get = fn (string $key) => isset($index[$key]) ? trim((string) ($row[$index[$key]] ?? '')) : '';
274:                 $rows[] = ['line' => $line, 'variant_id' => $get('variant_id'), 'sku' => $get('sku'),
275:                     'price' => $get('price'), 'min_qty' => $get('min_qty') === '' ? '1' : $get('min_qty'),
276:                     'starts_at' => $get('starts_at') === '' ? null : $get('starts_at'),
277:                     'ends_at' => $get('ends_at') === '' ? null : $get('ends_at')];
278:             }
279:         } finally {
280:             fclose($handle);
281:         }
282: 
283:         $ids = array_values(array_filter(array_map(fn ($row) => filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]), $rows)));
284:         $skus = [];
285:         foreach ($rows as $row) {
286:             $skus[] = $row['sku'];
287:             $skus[] = $this->unescapeCsvText($row['sku']);
288:         }
289:         $variants = ProductVariant::query()->where('is_active', true)
290:             ->where(fn ($q) => $q->whereIn('id', $ids)->orWhereIn('sku', array_unique($skus)))->get();
291:         $byId = $variants->keyBy('id');
292:         $bySku = $variants->keyBy('sku');
293:         $report = ['created' => 0, 'updated' => 0, 'skipped' => 0, 'errors' => []];
294:         $valid = [];
295:         foreach ($rows as $row) {
296:             try {
297:                 $variant = $row['variant_id'] !== ''
298:                     ? $byId->get(filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 0)
299:                     : ($bySku->get($row['sku']) ?? $bySku->get($this->unescapeCsvText($row['sku'])));
300:                 if ($variant === null || ($row['sku'] !== '' && $row['sku'] !== $variant->sku && $row['sku'] !== $this->csvText($variant->sku))) {
301:                     throw new BusinessException('الصنف غير موجود أو يوجد تعارض بين sku وvariant_id.');
302:                 }
303:                 $validator = Validator::make($row, [
304:                     'price' => ['required', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
305:                     'min_qty' => ['required', 'numeric', 'decimal:0,4', 'gt:0', 'max:99999999.9999'],
306:                     'starts_at' => ['nullable', 'date'], 'ends_at' => ['nullable', 'date'],
307:                 ]);
308:                 if ($validator->fails()) {
309:                     throw new BusinessException($validator->errors()->first());
310:                 }
311:                 $row['starts_at'] = $this->parseDate($row['starts_at'] ?? '');
312:                 $row['ends_at'] = $this->parseDate($row['ends_at'] ?? '');
313:                 $this->validateDates($row);
314:                 $valid[] = [...$row, 'product_variant_id' => $variant->id];
315:             } catch (BusinessException $exception) {
316:                 $report['skipped']++;
317:                 $report['errors'][] = ['line' => $row['line'], 'message' => $exception->getMessage()];
318:             }
319:         }
320:         DB::transaction(function () use ($valid, $priceList, &$report): void {
321:             PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
322:             foreach ($valid as $row) {
323:                 $item = PriceListItem::query()->updateOrCreate([
324:                     'price_list_id' => $priceList->id, 'product_variant_id' => $row['product_variant_id'], 'min_qty' => $row['min_qty'],
325:                 ], ['price' => $row['price'], 'starts_at' => $row['starts_at'], 'ends_at' => $row['ends_at']]);
326:                 $item->wasRecentlyCreated ? $report['created']++ : $report['updated']++;
327:             }
328:         });
329: 
330:         return $report;
331:     }
