333:     private function unescapeCsvText(string $value): string
334:     {
335:         return str_starts_with($value, "'") && $this->csvText(substr($value, 1)) === $value ? substr($value, 1) : $value;
336:     }
337: 
338:     /**
339:      * تحليل صارم للتواريخ: Y-m-d أو Y-m-d H:i:s أو ISO-8601 مع إزاحة فقط.
340:      * القيم بلا إزاحة تُفسَّر بمنطقة عمل (business_timezone) وتُخزَّن UTC —
341:      * لا strtotime: لا "next monday" ولا خلط بين التنسيقين الأمريكي والأوروبي.
342:      */
343:     private function parseDate(string $value): ?string
344:     {
345:         $value = trim($value);
346:         if ($value === '') {
347:             return null;
348:         }
349: 
350:         $businessTz = (string) config('app.business_timezone', 'Africa/Cairo');
351:         foreach (['Y-m-d\TH:i:sP', 'Y-m-d H:i:s', 'Y-m-d'] as $format) {
352:             try {
353:                 $parsed = Carbon::rawCreateFromFormat($format, $value, $businessTz);
354:             } catch (\Throwable) {
355:                 $parsed = false;
356:             }
357:             if ($parsed !== false && $parsed->format($format) === $value) {
358:                 return $parsed->utc()->format('Y-m-d H:i:s');
359:             }
360:         }
361: 
362:         throw new BusinessException("تاريخ غير صالح: {$value} — الصيغ المقبولة: Y-m-d أو Y-m-d H:i:s أو ISO-8601 مع إزاحة.");
363:     }
364: 
365:     /** تطبيع starts_at/ends_at القادمة من الـ API لنفس قواعد parseDate قبل الحفظ. */
366:     private function normalizeDates(array $data): array
367:     {
368:         foreach (['starts_at', 'ends_at'] as $field) {
369:             if (! array_key_exists($field, $data) || $data[$field] === null) {
370:                 continue;
371:             }
372:             $data[$field] = $data[$field] instanceof DateTimeInterface
373:                 ? Carbon::instance($data[$field])->utc()->format('Y-m-d H:i:s')
374:                 : $this->parseDate((string) $data[$field]);
375:         }
376: 
377:         return $data;
378:     }
