380:     // ----- نطاق الفرع (M4): الموظف المقيد لا يرى/يعدّل إلا قوائم فرعه -----
381:     // مجموعات العملاء كيان مركزي بلا فرع بالتصميم، فلا ينطبق عليها هذا التقييد.
382: 
383:     private function restrictedBranch(?User $user): ?int
384:     {
385:         return $user === null ? null : app(BranchAccess::class)->restrictedBranch($user);
386:     }
387: 
388:     public function assertListAccess(?User $user, PriceList $priceList): void
389:     {
390:         $restricted = $this->restrictedBranch($user);
391:         if ($restricted !== null && $priceList->branch_id !== $restricted) {
392:             throw new AuthorizationException('قائمة الأسعار هذه خارج نطاق فرعك.');
393:         }
394:     }
395: 
396:     private function validateDates(array $data, PriceList|PriceListItem|null $model = null): void
397:     {
398:         $start = array_key_exists('starts_at', $data) ? $data['starts_at'] : $model?->starts_at;
399:         $end = array_key_exists('ends_at', $data) ? $data['ends_at'] : $model?->ends_at;
400:         if ($start !== null && $end !== null && Carbon::parse($end)->lt(Carbon::parse($start))) {
401:             throw new BusinessException('نهاية صلاحية السعر يجب ألا تسبق بدايتها.');
402:         }
403:     }
