  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Enums\PriceListType;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Customer;
 12: use App\Models\PriceListItem;
 13: use App\Models\ProductVariant;
 14: use Carbon\Carbon;
 15: use Illuminate\Database\Eloquent\Builder;
 16: 
 17: /**
 18:  * محرك التسعير المركزي — يُستدعى من المتجر والجملة والـ POS ولوحة الإدارة.
 19:  *
 20:  * شجرة الأولويات:
 21:  * 1. سعر خاص بالعميل (customer_specific)
 22:  * 2. سعر مجموعة العميل (customer_group)
 23:  * 3. قائمة النوع (wholesale/distributor للمعتمدين فقط، وإلا retail)
 24:  * 4. السعر الأساسي للمتغير (base_price، المتوافق مع retail_price من المرحلة 2).
 25:  *
 26:  * خصم مجموعة العميل (discount_percentage) لا يصنع مستوى مستقلًا: يُطبق فوق ناتج
 27:  * المستويين 3/4 (سعر القناة)، ولا يُخصم من سعر خاص بالعميل أو سعر قائمة المجموعة.
 28:  * متغير بلا retail_price ولا قائمة مطابقة = غير مُسعَّر، ويرمي BusinessException.
 29:  *
 30:  * داخل كل مستوى: القائمة المخصصة للفرع أولًا، ثم أعلى شريحة كمية محققة،
 31:  * ثم أولوية القائمة، ثم السعر الأقل.
 32:  */
 33: class PricingService
 34: {
 35:     /**
 36:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
 37:      */
 38:     public function resolve(
 39:         ProductVariant $variant,
 40:         ?Customer $customer = null,
 41:         float $qty = 1,
 42:         ?int $branchId = null,
 43:     ): array {
 44:         if (! is_finite($qty) || $qty <= 0) {
 45:             throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
 46:         }
 47:         $now = Carbon::now();
 48: 
 49:         $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
 50:         $channel = $this->channelFor($customer);
 51:         $eligibleCustomer = $customer !== null && $customer->status === CustomerStatus::Approved;
 52: 
 53:         // الأولوية 1: سعر خاص بالعميل
 54:         if ($eligibleCustomer) {
 55:             $item = $this->ordered((clone $baseQuery)
 56:                 ->where('price_lists.type', PriceListType::CustomerSpecific)
 57:                 ->where('price_lists.customer_id', $customer->id)
 58:             )->first();
 59: 
 60:             if ($item !== null) {
 61:                 return $this->formatResponse((float) $item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
 62:             }
 63:         }
 64: 
 65:         // الأولوية 2: سعر مجموعة العميل
 66:         $group = $eligibleCustomer ? $customer->customerGroup()->where('is_active', true)->first() : null;
 67:         if ($group !== null) {
 68:             $item = $this->ordered((clone $baseQuery)
 69:                 ->where('price_lists.type', PriceListType::CustomerGroup)
 70:                 ->where('price_lists.customer_group_id', $group->id)
 71:             )->first();
 72: 
 73:             if ($item !== null) {
 74:                 return $this->formatResponse((float) $item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
 75:             }
 76:         }
 77: 
 78:         // الأولوية 3: قائمة نوع العميل (أو القطاعي افتراضيًا)
 79:         $item = $this->ordered((clone $baseQuery)
 80:             ->where('price_lists.type', $channel)
 81:         )->first();
 82: 
 83:         if ($item !== null) {
 84:             $channelPrice = (float) $item->price;
 85:             $channelListId = (int) $item->price_list_id;
 86:             $channelSource = $channel->value;
 87:         } elseif ($variant->retail_price === null) {
 88:             // الأولوية 4 مستحيلة: لا قائمة مطابقة ولا سعر قطاعي — الصنف غير مُسعَّر
 89:             // ولا يجوز أن يخرج بسعر صفر ليُباع مجانًا.
 90:             throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
 91:         } else {
 92:             // الأولوية 4: السعر الأساسي الموحد؛ أسعار الجملة والموزعين تأتي من القوائم.
 93:             $channelPrice = $this->basePrice($variant, $channel);
 94:             $channelListId = null;
 95:             $channelSource = 'base_price';
 96:         }
 97: 
 98:         // خصم مجموعة العميل يُطبق "فوق" سعر القناة المحسوب (قائمة القناة أو الأساسي)،
 99:         // ولا يتجاوزه أبدًا — فلا يخسر العميل سعر جملة/موزع أفضل بسبب خصم مجموعته.
100:         if ($group !== null && (float) $group->discount_percentage > 0) {
101:             return $this->formatResponse(
102:                 $channelPrice * (1 - (float) $group->discount_percentage / 100),
103:                 'customer_group_discount',
104:                 $channelListId,
105:                 $variant,
106:                 $channel,
107:             );
108:         }
109: 
110:         return $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);
111:     }
112: 
113:     /** قناة التسعير: الجملة/الموزع للحسابات المعتمدة فقط، وغير ذلك قطاعي. */
114:     private function channelFor(?Customer $customer): PriceListType
115:     {
116:         if ($customer !== null
117:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
118:             && $customer->status === CustomerStatus::Approved) {
119:             return PriceListType::from($customer->type->value);
120:         }
121: 
122:         return PriceListType::Retail;
123:     }
124: 
125:     private function basePrice(ProductVariant $variant, PriceListType $channel): float
126:     {
127:         return (float) $variant->base_price;
128:     }
129: 
130:     /** كل عناصر التسعير السارية لهذا المتغير والكمية والفرع والوقت. */
131:     private function eligibleItems(ProductVariant $variant, float $qty, ?int $branchId, Carbon $now): Builder
132:     {
133:         return PriceListItem::query()
134:             ->select('price_list_items.*')
135:             ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
136:             ->where('price_lists.is_active', true)
137:             ->where('price_list_items.product_variant_id', $variant->id)
138:             ->where('price_list_items.min_qty', '<=', $qty)
139:             ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
140:             ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
141:             ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
142:             ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
143:             ->where(function ($q) use ($branchId): void {
144:                 $q->whereNull('price_lists.branch_id');
145:                 if ($branchId !== null) {
146:                     $q->orWhere('price_lists.branch_id', $branchId);
147:                 }
148:             });
149:     }
150: 
151:     /** ترتيب داخل المستوى الواحد: فرع مخصص أولًا، أعلى شريحة، أعلى أولوية، أقل سعر. */
152:     private function ordered(Builder $query): Builder
153:     {
154:         return $query
155:             ->orderByRaw('price_lists.branch_id IS NULL ASC')
156:             ->orderByDesc('price_list_items.min_qty')
157:             ->orderByDesc('price_lists.priority')
158:             ->orderBy('price_list_items.price');
159:     }
160: 
161:     /**
162:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
163:      */
164:     private function formatResponse(float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
165:     {
166:         return [
167:             'unit_price' => round($unitPrice, 2),
168:             'base_price' => round($this->basePrice($variant, $channel), 2),
169:             'source' => $source,
170:             'price_list_id' => $priceListId,
171:         ];
172:     }
