 28:     private const ALL_PERMISSIONS = [
 29:         'inventory.view', 'inventory.adjust', 'inventory.all_branches',
 30:         'transfers.view', 'transfers.create', 'transfers.update', 'transfers.delete',
 31:         'transfers.approve', 'transfers.ship', 'transfers.receive',
