 41:     // ---------- InventoryService / Ledger ----------
 42: 
 43:     public function test_record_movement_creates_level_and_ledger_entry(): void
 44:     {
 45:         $admin = $this->staffWithPermissions(self::ALL_PERMISSIONS);
 46:         $variant = ProductVariant::factory()->create();
 47:         $branch = Branch::factory()->create();
 48: 
 49:         $movement = app(InventoryService::class)->recordMovement([
 50:             'product_variant_id' => $variant->id,
 51:             'branch_id' => $branch->id,
 52:             'type' => StockMovementType::AdjustmentIn,
 53:             'affected_bucket' => StockBucket::OnHand,
 54:             'quantity' => 10,
 55:             'created_by' => $admin->id,
 56:         ]);
 57: 
 58:         $this->assertSame('10.0000', $movement->balance_after);
 59:         $this->assertSame('0.0000', $movement->balance_before);
 60:         $this->assertStringStartsWith('MOV-', $movement->reference_number);
 61: 
 62:         $level = StockLevel::query()->where('product_variant_id', $variant->id)->where('branch_id', $branch->id)->first();
 63:         $this->assertSame('10.0000', $level->on_hand);
 64:         $this->assertSame(10.0, $level->available);
 65:     }
