208:     public function test_transfer_full_lifecycle_with_shortage(): void
209:     {
210:         $admin = $this->staffWithPermissions(self::ALL_PERMISSIONS);
211:         $token = $admin->createToken('test')->plainTextToken;
212:         $variant = ProductVariant::factory()->create();
213:         $from = Branch::factory()->create();
214:         $to = Branch::factory()->create();
215: 
216:         $this->seedStock($token, $branch = $from, $variant, 20);
217: 
218:         $transfer = $this->requestWithToken($token, 'POST', '/api/v1/admin/transfers', [
219:             'from_branch_id' => $from->id,
220:             'to_branch_id' => $to->id,
221:             'items' => [['product_variant_id' => $variant->id, 'requested_qty' => 8]],
222:         ])->assertCreated()->json('data');
223:         $transferId = $transfer['id'];
224: 
225:         // الاعتماد: حجز 8 عند المرسل
226:         $this->requestWithToken($token, 'POST', "/api/v1/admin/transfers/{$transferId}/approve", [])->assertOk();
227:         $levelFrom = $this->level($variant->id, $from->id);
228:         $this->assertSame('8.0000', $levelFrom->reserved);
229:         $this->assertSame(12.0, $levelFrom->available);
230: 
231:         // الشحن: خروج فعلي وفك حجز و in_transit عند المستلم
232:         $this->requestWithToken($token, 'POST', "/api/v1/admin/transfers/{$transferId}/ship", [])->assertOk();
233:         $levelFrom = $this->level($variant->id, $from->id);
234:         $this->assertSame('12.0000', $levelFrom->on_hand);
235:         $this->assertSame('0.0000', $levelFrom->reserved);
236:         $this->assertSame('8.0000', $this->level($variant->id, $to->id)->in_transit);
237: 
238:         // الاستلام بعجز: شُحن 8 واستُلم 6
239:         $itemId = $transfer['items'][0]['id'];
240:         $response = $this->requestWithToken($token, 'POST', "/api/v1/admin/transfers/{$transferId}/receive", [
241:             'items' => [['id' => $itemId, 'received_qty' => 6]],
242:         ])->assertOk();
243: 
244:         $levelTo = $this->level($variant->id, $to->id);
245:         $this->assertSame('0.0000', $levelTo->in_transit);
246:         $this->assertSame('6.0000', $levelTo->on_hand);
247:         $this->assertSame('received', $response->json('data.status'));
248:         $this->assertStringContainsString('عجز', (string) $response->json('data.notes'));
249: 
250:         $shortage = StockMovement::query()
251:             ->where('type', StockMovementType::TransferShortage)
252:             ->where('affected_bucket', StockBucket::InTransit)
253:             ->first();
254:         $this->assertNotNull($shortage);
255:         $this->assertSame('-2.0000', $shortage->quantity);
256:     }
