379:     // ---------- Helpers ----------
380: 
381:     private function seedStock(string $token, Branch $branch, ProductVariant $variant, float $qty): void
382:     {
383:         $this->requestWithToken($token, 'POST', '/api/v1/admin/inventory/adjustments', [
384:             'branch_id' => $branch->id,
385:             'items' => [['product_variant_id' => $variant->id, 'adjustment_type' => 'increase', 'quantity' => $qty]],
386:         ])->assertCreated();
387:     }
388: 
389:     private function level(int $variantId, int $branchId): StockLevel
390:     {
391:         return StockLevel::query()
392:             ->where('product_variant_id', $variantId)
393:             ->where('branch_id', $branchId)
394:             ->whereNull('location_id')
395:             ->firstOrFail();
396:     }
397: 
398:     private function staffWithPermissions(array $permissions): User
399:     {
400:         foreach ($permissions as $permission) {
401:             Permission::findOrCreate($permission, 'staff');
402:         }
403:         $staff = User::factory()->create();
404:         $staff->givePermissionTo($permissions);
405: 
406:         return $staff;
407:     }
408: 
409:     private function requestWithToken(string $token, string $method, string $uri, array $payload = []): TestResponse
410:     {
411:         Auth::forgetGuards();
412: 
413:         return $this->withToken($token)->json($method, $uri, $payload);
414:     }
