289:     private function customer(CustomerType $type, CustomerStatus $status, ?int $groupId = null): Customer
290:     {
291:         return Customer::query()->create([
292:             'name' => 'عميل '.uniqid(),
293:             'email' => uniqid().'@example.com',
294:             'phone' => '010'.random_int(10000000, 99999999),
295:             'password' => Hash::make('password'),
296:             'type' => $type,
297:             'status' => $status,
298:             'customer_group_id' => $groupId,
