302:     private function staffWithPermissions(array $permissions): User
303:     {
304:         foreach ($permissions as $permission) {
305:             Permission::findOrCreate($permission, 'staff');
306:         }
307:         $staff = User::factory()->create();
308:         $staff->givePermissionTo($permissions);
309: 
310:         return $staff;
311:     }
