38:         $emailKey = hash('sha256', Str::transliterate(Str::lower(trim($credentials['email']))));
39:         RateLimiter::clear('admin-login-email:'.$emailKey);
40:         RateLimiter::clear('admin-login-email-hour:'.$emailKey);
