 17: use Carbon\Carbon;
 18: use Illuminate\Database\Eloquent\Collection as EloquentCollection;
 19: use Illuminate\Http\JsonResponse;
 20: use Illuminate\Http\Request;
 21: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 22: use Illuminate\Routing\Controllers\HasMiddleware;
 23: use Illuminate\Routing\Controllers\Middleware;
 24: use Illuminate\Validation\Rule;
 25: 
 26: class InventoryController extends Controller implements HasMiddleware
 27: {
 28:     public function __construct(private readonly InventoryService $inventory) {}
 29: 
 30:     public static function middleware(): array
 31:     {
 32:         return [
 33:             new Middleware('can:inventory.view', only: ['index', 'movements']),
 34:             new Middleware('can:inventory.adjust', only: ['adjustments']),
 35:         ];
 36:     }
 37: 
 38:     /** قائمة أرصدة المخزون الحالية مع الفلاتر والمتاح المحسوب. */
 39:     public function index(Request $request): AnonymousResourceCollection
 40:     {
 41:         $filters = $request->validate([
 42:             'branch_id' => ['nullable', 'integer', 'min:1'],
 43:             'location_id' => ['nullable', 'integer', 'min:1'],
 44:             'product_id' => ['nullable', 'integer', 'min:1'],
 45:             'product_variant_id' => ['nullable', 'integer', 'min:1'],
 46:             'low_stock' => ['nullable', 'boolean'],
 47:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 48:         ]);
 49: 
 50:         $levels = StockLevel::query()
 51:             ->when(app(BranchAccess::class)->restrictedBranch($request->user()), fn ($q, $branch) => $q->where('branch_id', $branch))
 52:             ->with(['variant.product', 'branch', 'location'])
 53:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 54:             ->when($filters['location_id'] ?? null, fn ($q, $v) => $q->where('location_id', $v))
 55:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
 56:             ->when($filters['product_id'] ?? null, fn ($q, $v) => $q->whereHas('variant', fn ($vq) => $vq->where('product_id', $v)))
 57:             // حد إعادة الطلب الفعّال: مستوى الصف إن ضُبط (> 0)، وإلا مستوى المتغير نفسه
 58:             ->when($filters['low_stock'] ?? null, fn ($q) => $q
 59:                 ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 60:                 ->whereRaw('stock_levels.available <= COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0)')
 61:                 ->select('stock_levels.*'))
 62:             ->orderBy('branch_id')
 63:             ->orderBy('product_variant_id')
 64:             ->orderBy('id')
 65:             ->paginate($filters['per_page'] ?? 15);
 66: 
 67:         return StockLevelResource::collection($levels);
 68:     }
 69: 
 70:     /** سجل حركات دفتر الأستاذ من الأحدث للأقدم مع الفلاتر. */
 71:     public function movements(Request $request): AnonymousResourceCollection
 72:     {
 73:         $filters = $request->validate([
 74:             'branch_id' => ['nullable', 'integer', 'min:1'],
 75:             'location_id' => ['nullable', 'integer', 'min:1'],
 76:             'product_id' => ['nullable', 'integer', 'min:1'],
 77:             'product_variant_id' => ['nullable', 'integer', 'min:1'],
 78:             'type' => ['nullable', Rule::in(array_column(StockMovementType::cases(), 'value'))],
 79:             'from_date' => ['nullable', 'date'],
 80:             'to_date' => ['nullable', 'date'],
 81:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 82:         ]);
 83: 
 84:         $movements = StockMovement::query()
 85:             ->when(app(BranchAccess::class)->restrictedBranch($request->user()), fn ($q, $branch) => $q->where('branch_id', $branch))
 86:             ->with(['variant', 'branch', 'location', 'creator'])
 87:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 88:             ->when($filters['location_id'] ?? null, fn ($q, $v) => $q->where('location_id', $v))
 89:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
 90:             ->when($filters['product_id'] ?? null, fn ($q, $v) => $q->whereHas('variant', fn ($vq) => $vq->where('product_id', $v)))
 91:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 92:             // حدود الأيام بأيام العمل (business_timezone) لا UTC، والتخزين يظل UTC
 93:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('created_at', '>=', Carbon::parse($v, config('app.business_timezone'))->startOfDay()->utc()))
 94:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('created_at', '<', Carbon::parse($v, config('app.business_timezone'))->addDay()->startOfDay()->utc()))
 95:             ->orderByDesc('id')
 96:             // الدفتر append-only وسيكبر لملايين الصفوف: بلا COUNT(*) لكل صفحة
 97:             ->simplePaginate($filters['per_page'] ?? 15);
 98: 
 99:         return StockMovementResource::collection($movements);
100:     }
101: 
102:     /** تسوية يدوية: كل العناصر في transaction واحدة عبر InventoryService فقط. */
103:     public function adjustments(StoreAdjustmentRequest $request): JsonResponse
104:     {
105:         $idempotencyKey = $request->header('Idempotency-Key');
106:         if ($idempotencyKey !== null) {
107:             $idempotencyKey = trim($idempotencyKey);
108:             if ($idempotencyKey === '' || strlen($idempotencyKey) > 128) {
109:                 throw new BusinessException('قيمة Idempotency-Key غير صالحة (1 إلى 128 حرفًا).');
110:             }
111:         }
112: 
113:         $movements = $this->inventory->applyAdjustments($request->validated(), $request->user()->id, $idempotencyKey);
114: 
115:         return response()->json([
116:             'message' => 'تم تنفيذ التسوية بنجاح',
117:             'data' => StockMovementResource::collection((new EloquentCollection($movements))->load(['variant', 'branch', 'location'])),
118:         ], 201);
119:     }
