  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\InventoryIdempotencyKey;
 11: use App\Models\Location;
 12: use App\Models\ProductVariant;
 13: use App\Models\StockLevel;
 14: use App\Models\StockMovement;
 15: use Illuminate\Database\QueryException;
 16: use Illuminate\Database\UniqueConstraintViolationException;
 17: use Illuminate\Support\Collection;
 18: use Illuminate\Support\Facades\DB;
 19: 
 20: /**
 21:  * القلب النابض للمخزون — الطريق الوحيد لتغيير أي رصيد في النظام.
 22:  *
 23:  * قاعدة صارمة: ممنوع تعديل stock_levels من أي Controller أو Model آخر.
 24:  * كل تغيير يمر من هنا: تسجيل حركة في دفتر الأستاذ (stock_movements) أولًا،
 25:  * ثم تحديث الرصيد — داخل نفس الـ transaction ومع قفل الصف.
 26:  */
 27: class InventoryService
 28: {
 29:     public function __construct(private readonly SettingService $settings) {}
 30: 
 31:     /**
 32:      * الدالة المركزية الوحيدة لتغيير أي رصيد في النظام.
 33:      *
 34:      * @param  array{product_variant_id: int, branch_id: int, location_id?: int|null, type: StockMovementType|string, affected_bucket: StockBucket|string, quantity: float|int|string, unit_cost?: float|null, reference_type?: string|null, reference_id?: int|null, created_by?: int|null, notes?: string|null}  $data
 35:      */
 36:     public function recordMovement(array $data, ?StockLevel $prelockedLevel = null): StockMovement
 37:     {
 38:         return DB::transaction(function () use ($data, $prelockedLevel): StockMovement {
 39:             $rawQty = $data['quantity'];
 40:             if (! is_numeric($rawQty) || ! is_finite((float) $rawQty) || abs((float) $rawQty) > 99999999.9999) {
 41:                 throw new BusinessException('كمية الحركة غير صالحة.');
 42:             }
 43:             // Work in ten-thousandths to avoid floating point residues at zero.
 44:             $units = (int) round((float) $rawQty * 10000);
 45:             $qty = $units / 10000;
 46: 
 47:             if ($units === 0) {
 48:                 throw new BusinessException('كمية الحركة يجب ألا تساوي صفرًا.');
 49:             }
 50: 
 51:             $type = $data['type'] instanceof StockMovementType ? $data['type'] : StockMovementType::from($data['type']);
 52:             $bucket = $data['affected_bucket'] instanceof StockBucket ? $data['affected_bucket'] : StockBucket::from($data['affected_bucket']);
 53:             $this->assertValidMovementSemantics($type, $bucket, $units);
 54:             $locationId = $data['location_id'] ?? null;
 55: 
 56:             // صف مقفول مسبقًا من المستدعي (lockLevels): لا إعادة قفل ولا فحص موقع —
 57:             // المستدعي ضمن الصف والموقع عند القفل. خلاف ذلك نقفل هنا ونتحقق.
 58:             if ($prelockedLevel !== null) {
 59:                 if ((int) $prelockedLevel->product_variant_id !== (int) $data['product_variant_id']
 60:                     || (int) $prelockedLevel->branch_id !== (int) $data['branch_id']
 61:                     || ($prelockedLevel->location_id === null ? null : (int) $prelockedLevel->location_id) !== ($locationId === null ? null : (int) $locationId)) {
 62:                     throw new \LogicException('الصف المقفول مسبقًا لا يطابق مفتاح الحركة.');
 63:                 }
 64:                 $stock = $prelockedLevel;
 65:             } else {
 66:                 if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $data['branch_id'])->exists()) {
 67:                     throw new BusinessException('الموقع لا يتبع الفرع المحدد.');
 68:                 }
 69: 
 70:                 $stock = $this->lockLevels([[
 71:                     'product_variant_id' => $data['product_variant_id'],
 72:                     'branch_id' => $data['branch_id'],
 73:                     'location_id' => $locationId,
 74:                 ]])->first();
 75:             }
 76: 
 77:             $bucketKey = $bucket->value;
 78:             $before = (float) $stock->{$bucketKey};
 79:             $afterUnits = (int) round($before * 10000) + $units;
 80:             $after = $afterUnits / 10000;
 81:             if ($afterUnits > 999999999999) {
 82:                 throw new BusinessException('الرصيد يتجاوز الحد المسموح.');
 83:             }
 84: 
 85:             // 2. التحقق: الرصيد المستهدف لا ينزل تحت الصفر
 86:             if ($after < 0) {
 87:                 throw new BusinessException("الرصيد غير كافٍ في ({$bucketKey}) لإتمام العملية.");
 88:             }
 89: 
 90:             // 3. التحقق: الكمية المتاحة للبيع لا تصبح سالبة بعد الحركة
 91:             //    (يغطي حجز/تالف جديد أكبر من المتاح، وسحب فعلي يبتلع محجوزًا أو تالفًا)
 92:             $onHand = $bucket === StockBucket::OnHand ? $after : (float) $stock->on_hand;
 93:             $reserved = $bucket === StockBucket::Reserved ? $after : (float) $stock->reserved;
 94:             $damaged = $bucket === StockBucket::Damaged ? $after : (float) $stock->damaged;
 95:             $availableAfter = (int) round($onHand * 10000) - (int) round($reserved * 10000) - (int) round($damaged * 10000);
 96: 
 97:             if ($availableAfter < 0) {
 98:                 $availableNow = (float) $stock->on_hand - (float) $stock->reserved - (float) $stock->damaged;
 99: 
100:                 throw new BusinessException("الكمية المتاحة للبيع ({$availableNow}) غير كافية لإتمام العملية.");
101:             }
102: 
103:             // منفّذ الحركة إلزامي: من console/queue بلا مستخدم مصادق وبلا created_by
104:             // صريح، الفشل الواضح أفضل من QueryException على قيد NOT NULL.
105:             $createdBy = $data['created_by'] ?? auth()->id();
106:             if ($createdBy === null) {
107:                 throw new \LogicException('recordMovement يتطلب created_by صريحًا عند غياب مستخدم مصادق.');
108:             }
109: 
110:             // مرجع الدفتر يُخزن بالاسم القصير من morph map إن وُجد (stock_transfer/stocktake)
111:             // حتى لا تكسر إعادة تسمية الكلاسات أثر التدقيق؛ الأسماء الكاملة القديمة تظل مقروءة.
112:             $referenceType = $data['reference_type'] ?? null;
113:             if (is_string($referenceType) && class_exists($referenceType)) {
114:                 $referenceType = (new $referenceType)->getMorphClass();
115:             }
116: 
117:             // 4. تسجيل الحركة في دفتر الأستاذ (Ledger)
118:             $movement = StockMovement::query()->create([
119:                 'reference_number' => $this->settings->generateNextNumber('movement'),
120:                 'product_variant_id' => $data['product_variant_id'],
121:                 'branch_id' => $data['branch_id'],
122:                 'location_id' => $locationId,
123:                 'type' => $type,
124:                 'affected_bucket' => $bucket,
125:                 'quantity' => $qty,
126:                 'balance_before' => $before,
127:                 'balance_after' => $after,
128:                 'unit_cost' => $data['unit_cost'] ?? null,
129:                 'reference_type' => $referenceType,
130:                 'reference_id' => $data['reference_id'] ?? null,
131:                 'created_by' => $createdBy,
132:                 'notes' => $data['notes'] ?? null,
133:             ]);
134: 
135:             // 5. تحديث جدول الأرصدة من واقع الحركة
136:             $stock->{$bucketKey} = $after;
137:             $stock->save();
138: 
139:             return $movement;
140:         });
141:     }
