143:     /**
144:      * تسوية يدوية متعددة العناصر داخل transaction واحدة (أي فشل يلغي الكل).
145:      *
146:      * مع مفتاح عدم تكرار (Idempotency-Key): يُدرج المفتاح داخل نفس الـ transaction،
147:      * فالتكرار المتزامن يصطدم بالقيد الفريد بعد commit الأول ويعيد الحركات المحفوظة،
148:      * ونفس المفتاح بحمولة مختلفة يُرفض 409، وفشل الطلب يلغي المفتاح معه.
149:      *
150:      * @param  array{branch_id: int, location_id?: int|null, items: list<array{product_variant_id: int, adjustment_type: string, quantity: float|int|string, reason?: string|null}>}  $payload
151:      * @return list<StockMovement>
152:      */
153:     public function applyAdjustments(array $payload, int $userId, ?string $idempotencyKey = null): array
154:     {
155:         if ($idempotencyKey === null) {
156:             return $this->executeAdjustments($payload, $userId);
157:         }
158: 
159:         $requestHash = hash('sha256', json_encode($this->canonicalize($payload), JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION));
160: 
161:         try {
162:             return DB::transaction(function () use ($payload, $userId, $idempotencyKey, $requestHash): array {
163:                 $record = InventoryIdempotencyKey::query()->create([
164:                     'user_id' => $userId,
165:                     'key' => $idempotencyKey,
166:                     'request_hash' => $requestHash,
167:                 ]);
168: 
169:                 $movements = $this->executeAdjustments($payload, $userId);
170: 
171:                 $record->update([
172:                     'response' => array_map(fn (StockMovement $movement) => $movement->id, $movements),
173:                     'status_code' => 201,
174:                 ]);
175: 
176:                 return $movements;
177:             });
178:         } catch (UniqueConstraintViolationException) {
179:             $record = InventoryIdempotencyKey::query()
180:                 ->where('user_id', $userId)->where('key', $idempotencyKey)->first();
181: 
182:             if ($record === null) {
183:                 throw new BusinessException('تعارض في مفتاح عدم التكرار؛ أعد المحاولة.', [], 409);
184:             }
185: 
186:             if (! hash_equals($record->request_hash, $requestHash)) {
187:                 throw new BusinessException('مفتاح عدم التكرار هذا مستخدم مسبقًا مع بيانات مختلفة.', [], 409);
188:             }
189: 
190:             $ids = $record->response ?? [];
191:             $byId = StockMovement::query()->whereIn('id', $ids)->get()->keyBy('id');
192: 
193:             return array_values(array_filter(array_map(fn ($id) => $byId->get($id), $ids)));
194:         }
195:     }
196: 
197:     /**
198:      * @param  array{branch_id: int, location_id?: int|null, items: list<array{product_variant_id: int, adjustment_type: string, quantity: float|int|string, reason?: string|null}>}  $payload
199:      * @return list<StockMovement>
200:      */
201:     private function executeAdjustments(array $payload, int $userId): array
202:     {
203:         return DB::transaction(function () use ($payload, $userId): array {
204:             app(BranchAccess::class)->assertBranch($userId, (int) $payload['branch_id']);
205: 
206:             // M5: التعطيل لا يحبس الرصيد — عمليات الإخراج (decrease/تالف/شطب) مسموحة على
207:             // متغير/موقع معطّل لتصفية رصيده، والإدخال (increase) وحده يتطلب النشاط.
208:             if (collect($payload['items'])->contains('adjustment_type', 'increase')) {
209:                 $variants = ProductVariant::query()
210:                     ->whereIn('id', array_column($payload['items'], 'product_variant_id'))
211:                     ->get()->keyBy('id');
212:                 $location = ($payload['location_id'] ?? null) !== null ? Location::query()->find($payload['location_id']) : null;
213: 
214:                 foreach ($payload['items'] as $item) {
215:                     if ($item['adjustment_type'] !== 'increase') {
216:                         continue;
217:                     }
218:                     if ($variants->get($item['product_variant_id'])?->is_active === false) {
219:                         throw new BusinessException('لا يمكن الإدخال على متغير معطّل؛ فعّله أولًا أو استخدم عمليات الإخراج لتصفية رصيده.');
220:                     }
221:                     if ($location !== null && ! $location->is_active) {
222:                         throw new BusinessException('لا يمكن الإدخال إلى موقع معطّل؛ فعّله أولًا.');
223:                     }
224:                 }
225:             }
226:             $levels = $this->lockLevels(array_map(fn ($item) => [
227:                 'product_variant_id' => $item['product_variant_id'],
228:                 'branch_id' => $payload['branch_id'],
229:                 'location_id' => $payload['location_id'] ?? null,
230:             ], $payload['items']));
231:             $movements = [];
232: 
233:             foreach ($payload['items'] as $item) {
234:                 // الصف مقفول مسبقًا أعلاه — تُمرَّر حركتا العنصر عليه مباشرة.
235:                 $level = $levels->get($this->levelKey([
236:                     'product_variant_id' => $item['product_variant_id'],
237:                     'branch_id' => $payload['branch_id'],
238:                     'location_id' => $payload['location_id'] ?? null,
239:                 ]));
240:                 if (in_array($item['adjustment_type'], ['write_off_damaged', 'restore_damaged'], true)) {
241:                     $base = [
242:                         'product_variant_id' => $item['product_variant_id'],
243:                         'branch_id' => $payload['branch_id'], 'location_id' => $payload['location_id'] ?? null,
244:                         'created_by' => $userId, 'notes' => $item['reason'] ?? null,
245:                         'quantity' => -abs((float) $item['quantity']),
246:                     ];
247:                     $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageRelease, 'affected_bucket' => StockBucket::Damaged], $level);
248:                     if ($item['adjustment_type'] === 'write_off_damaged') {
249:                         $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageWriteOff, 'affected_bucket' => StockBucket::OnHand], $level);
250:                     }
251: 
252:                     continue;
253:                 }
254:                 [$type, $bucket, $sign] = match ($item['adjustment_type']) {
255:                     'increase' => [StockMovementType::AdjustmentIn, StockBucket::OnHand, 1],
256:                     'decrease' => [StockMovementType::AdjustmentOut, StockBucket::OnHand, -1],
257:                     'mark_damaged' => [StockMovementType::Damage, StockBucket::Damaged, 1],
258:                     default => throw new BusinessException('نوع تسوية غير معروف: '.$item['adjustment_type']),
259:                 };
260: 
261:                 $movements[] = $this->recordMovement([
262:                     'product_variant_id' => $item['product_variant_id'],
263:                     'branch_id' => $payload['branch_id'],
264:                     'location_id' => $payload['location_id'] ?? null,
265:                     'type' => $type,
266:                     'affected_bucket' => $bucket,
267:                     'quantity' => $sign * abs((float) $item['quantity']),
268:                     'created_by' => $userId,
269:                     'notes' => $item['reason'] ?? null,
270:                 ], $level);
271:             }
272: 
273:             return $movements;
274:         });
275:     }
