277:     /** الرصيد الحالي لمتغير في فرع/موقع (للقطات الجرد ونحوها) — قراءة فقط. */
278:     public function levelFor(int $variantId, int $branchId, ?int $locationId): ?StockLevel
279:     {
280:         return StockLevel::query()
281:             ->where('product_variant_id', $variantId)
282:             ->where('branch_id', $branchId)
283:             ->where('location_id', $locationId)
284:             ->first();
285:     }
