287:     /** Acquire every stock key before a multi-item operation, in one global order. */
288:     public function lockLevels(array $keys): Collection
289:     {
290:         if (DB::transactionLevel() === 0) {
291:             throw new \LogicException('Stock locks require an active transaction.');
292:         }
293:         // انتظار محدود للأقفال داخل هذه المعاملة فقط؛ التنافس الطويل يتحول لرفض
294:         // واضح (409) بدل تعليق الطلب حتى مهلة PHP-FPM.
295:         DB::statement("SET LOCAL lock_timeout = '5s'");
296:         $keys = collect($keys)->unique(fn ($key) => $this->levelKey($key))
297:             ->sortBy(fn ($key) => [(int) $key['branch_id'], (int) ($key['location_id'] ?? 0), (int) $key['product_variant_id']]);
298:         if ($keys->isEmpty()) {
299:             return collect();
300:         }
301:         $now = now();
302:         DB::table('stock_levels')->insertOrIgnore($keys->map(fn ($key) => [
303:             'product_variant_id' => $key['product_variant_id'], 'branch_id' => $key['branch_id'],
304:             'location_id' => $key['location_id'] ?? null, 'created_at' => $now, 'updated_at' => $now,
305:         ])->values()->all());
306: 
307:         try {
308:             $levels = StockLevel::query()->where(function ($query) use ($keys): void {
309:                 foreach ($keys->groupBy(fn ($key) => $key['branch_id'].':'.($key['location_id'] ?? 0)) as $group) {
310:                     $identity = $group->first();
311:                     $query->orWhere(fn ($scope) => $scope->where('branch_id', $identity['branch_id'])
312:                         ->where('location_id', $identity['location_id'] ?? null)
313:                         ->whereIn('product_variant_id', $group->pluck('product_variant_id')->all()));
314:                 }
315:             })->orderBy('branch_id')->orderByRaw('location_id ASC NULLS FIRST')->orderBy('product_variant_id')
316:                 ->lockForUpdate()->get()->keyBy(fn ($stock) => $this->levelKey($stock->getAttributes()));
317:         } catch (QueryException $e) {
318:             if (($e->errorInfo[0] ?? $e->getCode()) === '55P03') {
319:                 throw new BusinessException('المخزون مشغول بعملية أخرى الآن؛ أعد المحاولة بعد لحظات.', [], 409);
320:             }
321: 
322:             throw $e;
323:         }
324: 
325:         return $levels;
326:     }
327: 
328:     public function levelKey(array $key): string
329:     {
330:         return $key['branch_id'].':'.($key['location_id'] ?? 0).':'.$key['product_variant_id'];
331:     }
332: 
333:     private function assertValidMovementSemantics(StockMovementType $type, StockBucket $bucket, int $units): void
334:     {
335:         [$allowed, $positive] = match ($type) {
336:             StockMovementType::PurchaseReceipt, StockMovementType::SaleReturn,
337:             StockMovementType::AdjustmentIn, StockMovementType::StocktakeGain, StockMovementType::TransferIn => [[StockBucket::OnHand], true],
338:             StockMovementType::Sale, StockMovementType::AdjustmentOut,
339:             StockMovementType::StocktakeLoss, StockMovementType::TransferOut,
340:             StockMovementType::DamageWriteOff => [[StockBucket::OnHand], false],
341:             StockMovementType::Damage => [[StockBucket::Damaged], true],
342:             StockMovementType::DamageRelease => [[StockBucket::Damaged], false],
343:             StockMovementType::Reserve => [[StockBucket::Reserved], true],
344:             StockMovementType::ReleaseReserve => [[StockBucket::Reserved], false],
345:             StockMovementType::TransferInTransit => [[StockBucket::InTransit], true],
346:             StockMovementType::TransferTransitRelease, StockMovementType::TransferShortage => [[StockBucket::InTransit], false],
347:         };
348:         if (! in_array($bucket, $allowed, true) || ($units > 0) !== $positive) {
349:             throw new BusinessException('نوع الحركة لا يطابق وعاء المخزون أو اتجاه الكمية.');
350:         }
351:     }
352: 
353:     /** ترتيب حتمي لمفاتيح الحمولة قبل الحوسبة (نفس البيانات = نفس البصمة دائمًا). */
354:     private function canonicalize(mixed $value): mixed
355:     {
356:         if (! is_array($value)) {
357:             return $value;
358:         }
359: 
360:         $isList = array_is_list($value);
361:         $mapped = array_map(fn ($item) => $this->canonicalize($item), $value);
362: 
363:         if (! $isList) {
364:             ksort($mapped);
365:         }
366: 
367:         return $mapped;
368:     }
