 17: /**
 18:  * جلسات الجرد الفعلي. لقطة system_qty بتتاخد من stock_levels وقت إنشاء العنصر،
 19:  * والاعتماد بيحوّل الفروق لحركات دفتر (فائض/عجز) عبر InventoryService فقط،
 20:  * وبعد الاعتماد الجلسة بتتقفل نهائيًا.
 21:  */
 22: class StocktakeService
 23: {
 24:     public function __construct(
 25:         private readonly InventoryService $inventory,
 26:         private readonly SettingService $settings,
 27:     ) {}
 28: 
 29:     public function paginate(array $filters): LengthAwarePaginator
 30:     {
 31:         return Stocktake::query()
 32:             ->when($filters['staff_branch_id'] ?? null, fn ($q, $branch) => $q->where('branch_id', $branch))
 33:             ->with(['branch', 'location', 'creator'])
 34:             ->withCount('items')
 35:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 36:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 37:             ->orderByDesc('id')
 38:             ->paginate($filters['per_page'] ?? 15);
 39:     }
 40: 
 41:     public function find(int $id): Stocktake
 42:     {
 43:         return Stocktake::query()
 44:             ->with(['items.variant', 'branch', 'location', 'creator', 'approver'])
 45:             ->findOrFail($id);
 46:     }
 47: 
 48:     public function create(array $data, int $userId): Stocktake
 49:     {
 50:         return DB::transaction(function () use ($data, $userId): Stocktake {
 51:             app(BranchAccess::class)->assertBranch($userId, (int) $data['branch_id']);
 52:             $stocktake = Stocktake::query()->create([
 53:                 'stocktake_number' => $this->settings->generateNextNumber('stocktake'),
 54:                 'branch_id' => $data['branch_id'],
 55:                 'location_id' => $data['location_id'] ?? null,
 56:                 'status' => StocktakeStatus::Draft,
 57:                 'created_by' => $userId,
 58:                 'notes' => $data['notes'] ?? null,
 59:             ]);
 60: 
 61:             $this->syncItems($stocktake, $data['items'] ?? []);
 62: 
 63:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
 64:         });
 65:     }
