 67:     public function update(Stocktake $stocktake, array $data, int $userId): Stocktake
 68:     {
 69:         return DB::transaction(function () use ($stocktake, $data, $userId): Stocktake {
 70:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
 71:             $this->assertEditable($stocktake);
 72:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
 73:             app(BranchAccess::class)->assertBranch($userId, (int) ($data['branch_id'] ?? $stocktake->branch_id));
 74: 
 75:             $branchId = $data['branch_id'] ?? $stocktake->branch_id;
 76:             $locationId = array_key_exists('location_id', $data) ? $data['location_id'] : $stocktake->location_id;
 77:             if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $branchId)->exists()) {
 78:                 throw new BusinessException('موقع الجرد لا يتبع الفرع المحدد.');
 79:             }
 80:             if (((int) $branchId !== $stocktake->branch_id || ($locationId === null ? null : (int) $locationId) !== $stocktake->location_id)
 81:                 && ! array_key_exists('items', $data) && $stocktake->items()->exists()) {
 82:                 throw new BusinessException('تغيير نطاق الجرد يتطلب إعادة إرسال العناصر والعد الفعلي.');
 83:             }
 84: 
 85:             if (isset($data['status'])) {
 86:                 $target = StocktakeStatus::from($data['status']);
 87:                 $allowed = match ($stocktake->status) {
 88:                     StocktakeStatus::Draft => [StocktakeStatus::InProgress, StocktakeStatus::Cancelled],
 89:                     StocktakeStatus::InProgress => [StocktakeStatus::Cancelled],
 90:                     default => [],
 91:                 };
 92: 
 93:                 if (! in_array($target, $allowed, true)) {
 94:                     throw new BusinessException("لا يمكن نقل الجرد من حالة {$stocktake->status->value} إلى {$target->value}.");
 95:                 }
 96: 
 97:                 $stocktake->status = $target;
 98:             }
 99: 
100:             $stocktake->fill([
101:                 'branch_id' => $data['branch_id'] ?? $stocktake->branch_id,
102:                 'location_id' => array_key_exists('location_id', $data) ? $data['location_id'] : $stocktake->location_id,
103:                 'notes' => array_key_exists('notes', $data) ? $data['notes'] : $stocktake->notes,
104:             ])->save();
105: 
106:             if (isset($data['items'])) {
107:                 $this->upsertItems($stocktake, $data['items']);
108:             }
109: 
110:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
111:         });
112:     }
113: 
114:     /**
115:      * الاعتماد: تحويل كل فارق غير صفري لحركة دفتر (stocktake_gain/stocktake_loss)
116:      * على on_hand في نطاق الجلسة (فرعها وموقعها)، ثم قفل الجلسة.
117:      */
118:     public function approve(Stocktake $stocktake, int $userId): Stocktake
119:     {
120:         return DB::transaction(function () use ($stocktake, $userId): Stocktake {
121:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
122:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
123:             $stocktake->load('items.variant');
124: 
125:             if (! in_array($stocktake->status, [StocktakeStatus::Draft, StocktakeStatus::InProgress], true)) {
126:                 throw new BusinessException('لا يمكن اعتماد جرد بحالة '.$stocktake->status->value.'.');
127:             }
128: 
129:             $uncounted = $stocktake->items->filter(fn ($item) => $item->counted_qty === null);
130: 
131:             if ($stocktake->items->isEmpty()) {
132:                 throw new BusinessException('لا يمكن اعتماد جرد بلا عناصر.');
133:             }
134: 
135:             if ($uncounted->isNotEmpty()) {
136:                 throw new BusinessException('لا يمكن الاعتماد: توجد عناصر لم تُعدّ بعد.');
137:             }
138: 
139:             $levels = $this->inventory->lockLevels($stocktake->items->map(fn ($item) => [
140:                 'product_variant_id' => $item->product_variant_id,
141:                 'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
142:             ])->all());
143: 
144:             // A count becomes stale after a stock change; never overwrite intervening sales/receipts.
145:             // اللقطة مربوطة بلحظة العد، فأي حركة بعدها تجعل الصنف محتاجًا إعادة عد —
146:             // ولا تُحدَّث اللقطة بإعادة الحفظ، بل بتغيير العدد أو بعلم recount فقط.
147:             $staleItemIds = [];
148:             $staleVariantIds = [];
149:             foreach ($stocktake->items as $item) {
150:                 $key = $this->inventory->levelKey([
151:                     'product_variant_id' => $item->product_variant_id,
152:                     'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
153:                 ]);
154:                 if ((int) round((float) $levels[$key]->on_hand * 10000) !== (int) round((float) $item->system_qty * 10000)) {
155:                     $staleItemIds[] = $item->id;
156:                     $staleVariantIds[] = $item->product_variant_id;
157:                 }
158:                 if ((int) round((float) $item->counted_qty * 10000) < (int) round((float) $levels[$key]->reserved * 10000) + (int) round((float) $levels[$key]->damaged * 10000)) {
159:                     throw new BusinessException('العد الفعلي أقل من المحجوز والتالف؛ راجع الحجوزات وسوِّ التالف قبل إعادة العد والاعتماد.');
160:                 }
161:             }
162: 
163:             if ($staleItemIds !== []) {
164:                 throw new BusinessException(
165:                     'توجد أصناف تغيّر رصيدها بعد عدّها وتحتاج إعادة عد قبل الاعتماد.',
166:                     ['recount_item_ids' => $staleItemIds, 'recount_variant_ids' => $staleVariantIds],
167:                 );
168:             }
169: 
170:             foreach ($stocktake->items as $item) {
171:                 $difference = (float) $item->difference;
172: 
173:                 if ($difference === 0.0) {
174:                     continue;
175:                 }
176: 
177:                 $key = $this->inventory->levelKey([
178:                     'product_variant_id' => $item->product_variant_id,
179:                     'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
180:                 ]);
181: 
182:                 $this->inventory->recordMovement([
183:                     'product_variant_id' => $item->product_variant_id,
184:                     'branch_id' => $stocktake->branch_id,
185:                     'location_id' => $stocktake->location_id,
186:                     'type' => $difference > 0 ? StockMovementType::StocktakeGain : StockMovementType::StocktakeLoss,
187:                     'affected_bucket' => StockBucket::OnHand,
188:                     'quantity' => $difference,
189:                     'unit_cost' => $item->variant?->cost_price,
190:                     'reference_type' => Stocktake::class,
191:                     'reference_id' => $stocktake->id,
192:                     'created_by' => $userId,
193:                     'notes' => 'تسوية جرد '.$stocktake->stocktake_number,
194:                 ], $levels[$key] ?? null);
195:             }
196: 
197:             $stocktake->update([
198:                 'status' => StocktakeStatus::Approved,
199:                 'approved_by' => $userId,
200:                 'approved_at' => now(),
201:             ]);
202: 
203:             return $stocktake->load(['items.variant', 'branch', 'location']);
204:         });
205:     }
