207:     public function delete(Stocktake $stocktake, int $userId): void
208:     {
209:         DB::transaction(function () use ($stocktake, $userId): void {
210:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
211:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
212: 
213:             if (! in_array($stocktake->status, [StocktakeStatus::Draft, StocktakeStatus::Cancelled], true)) {
214:                 throw new BusinessException('لا يمكن حذف جرد إلا في حالة المسودة أو الملغي.');
215:             }
216: 
217:             $stocktake->delete();
218:         });
219:     }
