221:     private function assertEditable(Stocktake $stocktake): void
222:     {
223:         if (in_array($stocktake->status, [StocktakeStatus::Approved, StocktakeStatus::Cancelled], true)) {
224:             throw new BusinessException('هذا الجرد مقفل ولا يقبل أي تعديل.');
225:         }
226:     }
