228:     /**
229:      * تسجيل العناصر مع لقطة system_qty من الرصيد الحالي في نطاق الجلسة.
230:      *
231:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null}>  $items
232:      */
233:     private function syncItems(Stocktake $stocktake, array $items): void
234:     {
235:         $levels = StockLevel::query()->where('branch_id', $stocktake->branch_id)
236:             ->where('location_id', $stocktake->location_id)
237:             ->whereIn('product_variant_id', array_column($items, 'product_variant_id'))
238:             ->get()->keyBy('product_variant_id');
239:         foreach ($items as $item) {
240:             $level = $levels->get($item['product_variant_id']);
241: 
242:             $stocktake->items()->create([
243:                 'product_variant_id' => $item['product_variant_id'],
244:                 'system_qty' => $level ? (float) $level->on_hand : 0,
245:                 'counted_qty' => $item['counted_qty'] ?? null,
246:             ]);
247:         }
248:     }
249: 
250:     /**
251:      * تحديث عناصر جرد قائم بدون كسر ربط اللقطة بلحظة العد:
252:      * - عنصر جديد يُنشأ بلقطة الآن.
253:      * - لقطة عنصر قائم لا تتجدد إلا إذا سُجّل counted_qty أو تغيّر، أو أُرسل recount=true.
254:      * - إعادة حفظ بنفس الأعداد (الواجهة ترسل المصفوفة كاملة) لا تلمس اللقطات.
255:      * - عنصر غائب من الحمولة يُحذف من الجرد.
256:      *
257:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null, recount?: bool|null}>  $items
258:      */
259:     private function upsertItems(Stocktake $stocktake, array $items): void
260:     {
261:         $existing = $stocktake->items()->get()->keyBy('product_variant_id');
262:         $levels = StockLevel::query()->where('branch_id', $stocktake->branch_id)
263:             ->where('location_id', $stocktake->location_id)
264:             ->whereIn('product_variant_id', array_column($items, 'product_variant_id'))
265:             ->get()->keyBy('product_variant_id');
266: 
267:         $keepIds = [];
268:         foreach ($items as $item) {
269:             $variantId = (int) $item['product_variant_id'];
270:             $currentOnHand = $levels->get($variantId) ? (float) $levels->get($variantId)->on_hand : 0.0;
271:             $row = $existing->get($variantId);
272: 
273:             if ($row === null) {
274:                 $created = $stocktake->items()->create([
275:                     'product_variant_id' => $variantId,
276:                     'system_qty' => $currentOnHand,
277:                     'counted_qty' => $item['counted_qty'] ?? null,
278:                 ]);
279:                 $keepIds[] = $created->id;
280: 
281:                 continue;
282:             }
283: 
284:             $keepIds[] = $row->id;
285:             $updates = [];
286: 
287:             if (array_key_exists('counted_qty', $item)) {
288:                 $updates['counted_qty'] = $item['counted_qty'];
289: 
290:                 $countChanged = $item['counted_qty'] !== null
291:                     && ($row->counted_qty === null || (float) $item['counted_qty'] !== (float) $row->counted_qty);
292: 
293:                 if ($countChanged || ! empty($item['recount'])) {
294:                     $updates['system_qty'] = $currentOnHand;
295:                 }
296:             } elseif (! empty($item['recount'])) {
297:                 $updates['system_qty'] = $currentOnHand;
298:             }
299: 
300:             if ($updates !== []) {
301:                 $row->update($updates);
302:             }
303:         }
304: 
305:         $stocktake->items()->whereNotIn('id', $keepIds)->delete();
306:     }
