 31: 
 32:     public function paginate(array $filters): LengthAwarePaginator
 33:     {
 34:         return StockTransfer::query()
 35:             ->when($filters['staff_branch_id'] ?? null, fn ($q, $branch) => $q->where(fn ($scope) => $scope->where('from_branch_id', $branch)->orWhere('to_branch_id', $branch)))
 36:             ->with(['fromBranch', 'toBranch', 'creator'])
 37:             ->when($filters['from_branch_id'] ?? null, fn ($q, $v) => $q->where('from_branch_id', $v))
 38:             ->when($filters['to_branch_id'] ?? null, fn ($q, $v) => $q->where('to_branch_id', $v))
 39:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 40:             ->orderByDesc('id')
 41:             ->paginate($filters['per_page'] ?? 15);
 42:     }
