 44:     public function find(int $id): StockTransfer
 45:     {
 46:         return StockTransfer::query()
 47:             ->with(['items.variant', 'items.fromLocation', 'items.toLocation', 'fromBranch', 'toBranch', 'creator', 'approver'])
 48:             ->findOrFail($id);
