 51:     public function create(array $data, int $userId): StockTransfer
 52:     {
 53:         return DB::transaction(function () use ($data, $userId): StockTransfer {
 54:             app(BranchAccess::class)->assertBranch($userId, (int) $data['from_branch_id']);
 55:             $transfer = StockTransfer::query()->create([
 56:                 'transfer_number' => $this->settings->generateNextNumber('transfer'),
 57:                 'from_branch_id' => $data['from_branch_id'],
 58:                 'to_branch_id' => $data['to_branch_id'],
 59:                 'status' => TransferStatus::Draft,
 60:                 'created_by' => $userId,
 61:                 'notes' => $data['notes'] ?? null,
 62:             ]);
 63: 
 64:             $this->syncItems($transfer, $data['items']);
 65: 
 66:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch', 'creator']);
 67:         });
 68:     }
