 70:     public function update(StockTransfer $transfer, array $data, int $userId): StockTransfer
 71:     {
 72:         return DB::transaction(function () use ($transfer, $data, $userId): StockTransfer {
 73:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
 74:             $this->assertStatus($transfer, TransferStatus::Draft, 'التعديل');
 75:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
 76:             app(BranchAccess::class)->assertBranch($userId, (int) ($data['from_branch_id'] ?? $transfer->from_branch_id));
 77: 
 78:             $fromBranch = $data['from_branch_id'] ?? $transfer->from_branch_id;
 79:             $toBranch = $data['to_branch_id'] ?? $transfer->to_branch_id;
 80:             if ((int) $fromBranch === (int) $toBranch) {
 81:                 throw new BusinessException('يجب اختلاف الفرع المرسل عن الفرع المستلم.');
 82:             }
 83:             $items = $data['items'] ?? $transfer->items->toArray();
 84:             foreach ($items as $item) {
 85:                 foreach (['from_location_id' => $fromBranch, 'to_location_id' => $toBranch] as $field => $branchId) {
 86:                     if (isset($item[$field]) && ! Location::query()->whereKey($item[$field])->where('branch_id', $branchId)->exists()) {
 87:                         throw new BusinessException('موقع التحويل لا يتبع الفرع المحدد.');
 88:                     }
 89:                 }
 90:             }
 91: 
 92:             $transfer->update([
 93:                 'from_branch_id' => $data['from_branch_id'] ?? $transfer->from_branch_id,
 94:                 'to_branch_id' => $data['to_branch_id'] ?? $transfer->to_branch_id,
 95:                 'notes' => array_key_exists('notes', $data) ? $data['notes'] : $transfer->notes,
 96:             ]);
 97: 
 98:             if (isset($data['items'])) {
 99:                 $transfer->items()->delete();
100:                 $this->syncItems($transfer, $data['items']);
101:             }
102: 
103:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch', 'creator']);
104:         });
105:     }
