107:     /** الاعتماد: حجز الكميات المعتمدة في الفرع المرسل حتى لا تُباع قبل الشحن. */
108:     public function approve(StockTransfer $transfer, array $itemsPayload, int $userId, ?string $expectedUpdatedAt = null): StockTransfer
109:     {
110:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId, $expectedUpdatedAt): StockTransfer {
111:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
112:             $transfer->load('items.variant');
113:             $this->assertPayloadMatchesLockedItems($transfer, $itemsPayload, $expectedUpdatedAt);
114:             $this->assertStatus($transfer, TransferStatus::Draft, 'الاعتماد');
115:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
116:             if ($transfer->items->sum(fn ($item) => (float) ($itemsPayload[$item->id] ?? $item->requested_qty)) <= 0) {
117:                 throw new BusinessException('يجب اعتماد كمية موجبة واحدة على الأقل؛ يمكن إلغاء التحويل بدلًا من اعتماده بصفر.');
118:             }
119:             $levels = $this->lockTransferLevels($transfer, true, false);
120: 
121:             foreach ($transfer->items as $item) {
122:                 $approvedQty = (float) ($itemsPayload[$item->id] ?? $item->requested_qty);
123: 
124:                 if ($approvedQty < 0 || $approvedQty > (float) $item->requested_qty) {
125:                     throw new BusinessException('الكمية المعتمدة يجب أن تكون بين صفر والكمية المطلوبة.');
126:                 }
127: 
128:                 $item->update(['approved_qty' => $approvedQty]);
129: 
130:                 if ($approvedQty > 0) {
131:                     $this->move([
132:                         'product_variant_id' => $item->product_variant_id,
133:                         'branch_id' => $transfer->from_branch_id,
134:                         'location_id' => $item->from_location_id,
135:                         'type' => StockMovementType::Reserve,
136:                         'affected_bucket' => StockBucket::Reserved,
137:                         'quantity' => $approvedQty,
138:                         'unit_cost' => $item->variant?->cost_price,
139:                         'reference_type' => StockTransfer::class,
140:                         'reference_id' => $transfer->id,
141:                         'created_by' => $userId,
142:                         'notes' => 'حجز لصالح تحويل '.$transfer->transfer_number,
143:                     ], $levels);
144:                 }
145:             }
146: 
147:             $transfer->update(['status' => TransferStatus::Approved, 'approved_by' => $userId]);
148: 
149:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
150:         });
151:     }
