163:                 throw new BusinessException('يجب شحن كمية موجبة واحدة على الأقل؛ يمكن إلغاء التحويل لفك الحجز.');
164:             }
165:             $levels = $this->lockTransferLevels($transfer, true, true);
166: 
167:             foreach ($transfer->items as $item) {
