169: 
170:                 if ($shippedQty < 0 || $shippedQty > (float) $item->approved_qty) {
171:                     throw new BusinessException('الكمية المشحونة يجب أن تكون بين صفر والكمية المعتمدة.');
172:                 }
173: 
174:                 $item->update(['shipped_qty' => $shippedQty]);
