180:                             'branch_id' => $transfer->from_branch_id,
181:                             'location_id' => $item->from_location_id,
182:                             'type' => StockMovementType::ReleaseReserve,
183:                             'affected_bucket' => StockBucket::Reserved,
184:                             'quantity' => -(float) $item->approved_qty,
185:                             'reference_type' => StockTransfer::class,
186:                             'reference_id' => $transfer->id,
187:                             'created_by' => $userId,
188:                             'notes' => 'فك حجز صنف غير مشحون من تحويل '.$transfer->transfer_number,
