192:                     continue;
193:                 }
194: 
195:                 $base = [
196:                     'product_variant_id' => $item->product_variant_id,
197:                     'unit_cost' => $item->variant?->cost_price,
198:                     'reference_type' => StockTransfer::class,
199:                     'reference_id' => $transfer->id,
200:                     'created_by' => $userId,
201:                 ];
202: 
203:                 // المرسل: فك الحجز ثم إخراج فعلي
204:                 $this->move([...$base,
205:                     'branch_id' => $transfer->from_branch_id,
206:                     'location_id' => $item->from_location_id,
207:                     'type' => StockMovementType::ReleaseReserve,
208:                     'affected_bucket' => StockBucket::Reserved,
209:                     'quantity' => -$shippedQty,
210:                     'notes' => 'فك حجز عند شحن تحويل '.$transfer->transfer_number,
211:                 ], $levels);
212:                 $this->move([...$base,
213:                     'branch_id' => $transfer->from_branch_id,
214:                     'location_id' => $item->from_location_id,
215:                     'type' => StockMovementType::TransferOut,
216:                     'affected_bucket' => StockBucket::OnHand,
217:                     'quantity' => -$shippedQty,
218:                     'notes' => 'شحن تحويل '.$transfer->transfer_number,
