251:     /** الاستلام: تسوية in_transit بالكامل، وإضافة المستلم فعليًا، وتسوية أي عجز كحركة مستقلة. */
252:     public function receive(StockTransfer $transfer, array $itemsPayload, int $userId, ?string $expectedUpdatedAt = null): StockTransfer
253:     {
254:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId, $expectedUpdatedAt): StockTransfer {
255:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
256:             $transfer->load('items.variant');
257:             $this->assertPayloadMatchesLockedItems($transfer, $itemsPayload, $expectedUpdatedAt);
258:             $this->assertStatus($transfer, TransferStatus::Shipped, 'الاستلام');
259:             app(BranchAccess::class)->assertBranch($userId, $transfer->to_branch_id);
260:             $levels = $this->lockTransferLevels($transfer, false, true);
261: 
262:             $shortageNotes = [];
263: 
264:             foreach ($transfer->items as $item) {
265:                 $receivedQty = (float) ($itemsPayload[$item->id] ?? $item->shipped_qty);
266:                 $shippedQty = (float) $item->shipped_qty;
267: 
268:                 if ($receivedQty < 0 || $receivedQty > $shippedQty) {
269:                     throw new BusinessException('الكمية المستلمة يجب أن تكون بين صفر والكمية المشحونة.');
270:                 }
271: 
272:                 $item->update(['received_qty' => $receivedQty]);
273: 
274:                 if ($shippedQty <= 0) {
275:                     continue;
276:                 }
277: 
278:                 $base = [
279:                     'product_variant_id' => $item->product_variant_id,
280:                     'branch_id' => $transfer->to_branch_id,
281:                     'location_id' => $item->to_location_id,
282:                     'unit_cost' => $item->variant?->cost_price,
283:                     'reference_type' => StockTransfer::class,
284:                     'reference_id' => $transfer->id,
285:                     'created_by' => $userId,
286:                 ];
287: 
288:                 // خروج الجزء المستلم من "في الطريق" ودخوله الرصيد الفعلي
289:                 if ($receivedQty > 0) {
290:                     $this->move([...$base,
291:                         'type' => StockMovementType::TransferTransitRelease,
292:                         'affected_bucket' => StockBucket::InTransit,
293:                         'quantity' => -$receivedQty,
294:                         'notes' => 'استلام تحويل '.$transfer->transfer_number,
295:                     ], $levels);
296:                     $this->move([...$base,
297:                         'type' => StockMovementType::TransferIn,
298:                         'affected_bucket' => StockBucket::OnHand,
299:                         'quantity' => $receivedQty,
300:                         'notes' => 'استلام تحويل '.$transfer->transfer_number,
301:                     ], $levels);
302:                 }
303: 
304:                 // العجز بين المشحون والمستلم: تسوية مستقلة موثقة من رصيد "في الطريق"
305:                 $shortage = round($shippedQty - $receivedQty, 4);
306:                 if ($shortage > 0) {
307:                     $this->move([...$base,
308:                         'type' => StockMovementType::TransferShortage,
309:                         'affected_bucket' => StockBucket::InTransit,
310:                         'quantity' => -$shortage,
311:                         'notes' => 'عجز عند استلام تحويل '.$transfer->transfer_number,
312:                     ], $levels);
313:                     $shortageNotes[] = "عجز {$shortage} وحدة في المتغير #{$item->product_variant_id}";
314:                 }
315:             }
316: 
317:             $notes = $transfer->notes;
318:             if ($shortageNotes !== []) {
319:                 $notes = trim(($notes ? $notes.' | ' : '').implode('؛ ', $shortageNotes));
320:             }
321: 
322:             $transfer->update(['status' => TransferStatus::Received, 'received_at' => now(), 'notes' => $notes]);
323: 
324:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
325:         });
326:     }
327: 
328:     /** الإلغاء: من المسودة مباشرة، ومن المعتمد بعد فك الحجز. المشحون لا يُلغى (يُستلم). */
329:     public function cancel(StockTransfer $transfer, int $userId): StockTransfer
330:     {
331:         return DB::transaction(function () use ($transfer, $userId): StockTransfer {
332:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
333:             $transfer->load('items.variant');
334:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
335: 
336:             if ($transfer->status === TransferStatus::Approved) {
337:                 $levels = $this->lockTransferLevels($transfer, true, false);
338:                 foreach ($transfer->items as $item) {
339:                     if ((float) $item->approved_qty <= 0) {
340:                         continue;
341:                     }
342: 
343:                     $this->move([
344:                         'product_variant_id' => $item->product_variant_id,
345:                         'branch_id' => $transfer->from_branch_id,
346:                         'location_id' => $item->from_location_id,
347:                         'type' => StockMovementType::ReleaseReserve,
348:                         'affected_bucket' => StockBucket::Reserved,
349:                         'quantity' => -(float) $item->approved_qty,
350:                         'reference_type' => StockTransfer::class,
351:                         'reference_id' => $transfer->id,
352:                         'created_by' => $userId,
353:                         'notes' => 'فك حجز عند إلغاء تحويل '.$transfer->transfer_number,
354:                     ], $levels);
355:                 }
356:             } elseif ($transfer->status !== TransferStatus::Draft) {
357:                 throw new BusinessException('لا يمكن إلغاء تحويل بحالة '.$transfer->status->value.'.');
358:             }
359: 
360:             $transfer->update(['status' => TransferStatus::Cancelled]);
361: 
362:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
363:         });
364:     }
365: 
366:     public function delete(StockTransfer $transfer, int $userId): void
367:     {
368:         DB::transaction(function () use ($transfer, $userId): void {
369:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
370:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
371: 
372:             if (! in_array($transfer->status, [TransferStatus::Draft, TransferStatus::Cancelled], true)) {
373:                 throw new BusinessException('لا يمكن حذف تحويل إلا في حالة المسودة أو الملغي.');
374:             }
375: 
376:             // تحويل اعتُمد ثم أُلغي له حركات دفتر (حجز/فك حجز) تشير إليه بلا FK؛
377:             // حذفه يترك مراجع يتيمة ويقطع أثر التدقيق — الإلغاء نفسه هو الحفظ الصحيح.
378:             if (StockMovement::query()->whereIn('reference_type', [StockTransfer::class, 'stock_transfer'])->where('reference_id', $transfer->id)->exists()) {
379:                 throw new BusinessException('لا يمكن حذف تحويل له حركات مخزون مسجلة في الدفتر؛ إلغاؤه يحفظ أثر التدقيق.');
380:             }
381: 
382:             $transfer->delete();
383:         });
384:     }
385: 
386:     /**
387:      * حماية من الحمولات القديمة: أي معرّف عنصر لا يتبع التحويل المقفول يُرفض بدل
388:      * تجاهله بصمت (التعديل بين تحقق الطلب والقفل كان يبدّل المعرّفات)، وطابع
389:      * expected_updated_at الاختياري يمنع اعتماد نسخة لم يراجعها المعتمد.
390:      */
391:     private function assertPayloadMatchesLockedItems(StockTransfer $transfer, array $itemsPayload, ?string $expectedUpdatedAt): void
392:     {
393:         $unknownIds = array_diff(array_map('intval', array_keys($itemsPayload)), $transfer->items->pluck('id')->map(fn ($id) => (int) $id)->all());
394: 
395:         if ($unknownIds !== []) {
396:             throw new BusinessException(
397:                 'توجد عناصر في الطلب لا تتبع هذا التحويل (المعرّفات: '.implode(', ', $unknownIds).'). أعد تحميل التحويل وراجع الكميات.',
398:                 ['unknown_item_ids' => array_values($unknownIds)],
399:                 409,
400:             );
401:         }
402: 
403:         if ($expectedUpdatedAt !== null
404:             && $transfer->updated_at->format('Y-m-d H:i:s') !== Carbon::parse($expectedUpdatedAt)->format('Y-m-d H:i:s')) {
405:             throw new BusinessException(
406:                 'تم تعديل هذا التحويل بعد تحميله. أعد تحميله وراجع الكميات قبل التنفيذ.',
407:                 ['current_updated_at' => $transfer->updated_at->toIso8601String()],
408:                 409,
409:             );
410:         }
411:     }
412: 
413:     private function assertStatus(StockTransfer $transfer, TransferStatus $expected, string $action): void
414:     {
415:         if ($transfer->status !== $expected) {
416:             throw new BusinessException("لا يمكن تنفيذ {$action} على تحويل بحالة {$transfer->status->value}.");
417:         }
418:     }
419: 
420:     /**
421:      * @param  list<array{product_variant_id: int, from_location_id?: int|null, to_location_id?: int|null, requested_qty: float|int|string}>  $items
422:      */
423:     private function syncItems(StockTransfer $transfer, array $items): void
424:     {
425:         $this->assertDistinctItems($items);
426:         foreach ($items as $item) {
427:             $transfer->items()->create([
428:                 'product_variant_id' => $item['product_variant_id'],
429:                 'from_location_id' => $item['from_location_id'] ?? null,
430:                 'to_location_id' => $item['to_location_id'] ?? null,
431:                 'requested_qty' => $item['requested_qty'],
432:             ]);
433:         }
434:     }
435: 
436:     private function assertDistinctItems(array $items): void
437:     {
438:         $keys = array_map(fn ($item) => $item['product_variant_id'].':'.($item['from_location_id'] ?? 0).':'.($item['to_location_id'] ?? 0), $items);
439:         if (count(array_unique($keys)) !== count($keys)) {
440:             throw new BusinessException('لا يجوز تكرار نفس الصنف وموقعي الإرسال والاستلام داخل التحويل.');
441:         }
442:     }
443: 
444:     /** حركة على صف مقفول مسبقًا ضمن $levels — بلا إعادة قفل أو فحص موقع. */
445:     private function move(array $data, Collection $levels): void
446:     {
447:         $level = $levels->get($this->inventory->levelKey([
448:             'product_variant_id' => $data['product_variant_id'],
449:             'branch_id' => $data['branch_id'],
450:             'location_id' => $data['location_id'] ?? null,
451:         ]));
452: 
453:         $this->inventory->recordMovement($data, $level);
454:     }
455: 
456:     private function lockTransferLevels(StockTransfer $transfer, bool $source, bool $destination): Collection
457:     {
458:         $keys = [];
459:         foreach ($transfer->items as $item) {
460:             if ($source) {
461:                 $keys[] = ['branch_id' => $transfer->from_branch_id, 'location_id' => $item->from_location_id, 'product_variant_id' => $item->product_variant_id];
462:             }
463:             if ($destination) {
464:                 $keys[] = ['branch_id' => $transfer->to_branch_id, 'location_id' => $item->to_location_id, 'product_variant_id' => $item->product_variant_id];
465:             }
466:         }
467: 
468:         return $this->inventory->lockLevels($keys);
469:     }
