 33:             'branch_id' => $branch->id,
 34:             'is_active' => true,
 35:         ]);
 36:         $staff->assignRole($role);
 37: 
 38:         $response = $this->postJson('/api/v1/admin/auth/login', [
 39:             'email' => '  ADMIN@Example.Test  ',
 40:             'password' => 'secret-password',
