 43:         $response->assertOk()
 44:             ->assertJsonPath('data.email', 'admin@example.test')
 45:             ->assertJsonPath('data.branch.id', $branch->id)
 46:             ->assertJsonPath('data.roles.0.name', 'Manager')
 47:             ->assertJsonPath('data.permissions.0', 'users.view')
 48:             ->assertJsonStructure(['data' => ['id', 'name', 'email', 'branch', 'roles', 'permissions'], 'token']);
 49: 
 50:         $token = $response->json('token');
 51:         $this->getAsToken($token, '/api/v1/admin/me')
 52:             ->assertOk()
 53:             ->assertJsonPath('data.id', $staff->id)
 54:             ->assertJsonPath('data.branch.name', $branch->name);
 55: 
 56:         $this->assertTrue(Hash::check('secret-password', $staff->refresh()->password));
