 14: class SettingService
 15: {
 16:     /** @var array<string, array{0: string, 1: int}> بادئة وحشو الترقيم لكل نوع — يُقرآن مرة واحدة لكل طلب (M11). */
 17:     private array $numberingConfig = [];
 18: 
 19:     private const CACHE_KEY = 'app_settings_static';
 20: 
 21:     private const CACHE_TTL_SECONDS = 3600;
 22: 
 23:     /** @var list<string> */
 24:     private const NUMBERING_COUNTER_KEYS = [
 25:         'invoice_next_number',
 26:         'order_next_number',
 27:         'purchase_order_next_number',
 28:         'quotation_next_number',
 29:         'movement_next_number',
 30:         'transfer_next_number',
 31:         'stocktake_next_number',
 32:     ];
 33: 
 34:     /**
 35:      * Return all settings grouped by their group name, with values cast to their declared types.
 36:      * Numbering counters are read fresh because they change for every generated document number.
 37:      *
 38:      * @return array<string, array<string, mixed>>
 39:      */
 40:     public function getAllGrouped(): array
 41:     {
 42:         $grouped = Cache::remember(self::CACHE_KEY, self::CACHE_TTL_SECONDS, function (): array {
 43:             return Setting::query()
 44:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
 45:                 ->orderBy('group')
 46:                 ->orderBy('key')
 47:                 ->get()
 48:                 ->groupBy('group')
 49:                 ->map(fn ($settings): array => $settings
 50:                     ->mapWithKeys(fn (Setting $setting): array => [
 51:                         $setting->key => $this->castValue($setting->value, $setting->type),
 52:                     ])
 53:                     ->all())
 54:                 ->all();
 55:         });
 56: 
 57:         $counters = Setting::query()
 58:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
 59:             ->orderBy('key')
 60:             ->get()
 61:             ->mapWithKeys(fn (Setting $setting): array => [
 62:                 $setting->key => $this->castValue($setting->value, $setting->type),
 63:             ])
 64:             ->all();
 65: 
 66:         if (isset($counters['movement_next_number'])) {
 67:             $counters['movement_next_number'] = $this->nextMovementNumber();
 68:         }
 69: 
 70:         if ($counters !== []) {
 71:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
 72:             ksort($grouped['numbering']);
 73:         }
 74: 
 75:         return $grouped;
 76:     }
 77: 
 78:     public function get(string $key, mixed $default = null): mixed
 79:     {
 80:         foreach ($this->getAllGrouped() as $settings) {
 81:             if (array_key_exists($key, $settings)) {
 82:                 return $settings[$key];
 83:             }
 84:         }
 85: 
 86:         return $default;
 87:     }
 88: 
 89:     /**
 90:      * Update a flat key/value map atomically and invalidate the cached settings after commit.
 91:      *
 92:      * @param  array<string, mixed>  $settings
 93:      *
 94:      * @throws JsonException
 95:      */
 96:     public function updateBatch(array $settings): void
 97:     {
 98:         DB::transaction(function () use ($settings): void {
 99:             $lockedSettings = Setting::query()
100:                 ->whereIn('key', array_keys($settings))
101:                 ->orderBy('key')
102:                 ->lockForUpdate()
103:                 ->get()
104:                 ->keyBy('key');
105: 
106:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
107: 
108:             if ($missingKeys !== []) {
109:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
110:             }
111: 
112:             foreach ($settings as $key => $value) {
113:                 /** @var Setting $setting */
114:                 $setting = $lockedSettings->get($key);
115: 
116:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
117:                     $value = max($this->counterValue($setting->value), $this->counterValue($value));
118:                     if ($key === 'movement_next_number') {
119:                         // Configuration changes are rare; lock the sequence only here, never per movement.
120:                         DB::statement('ALTER SEQUENCE stock_movement_number_seq INCREMENT BY 1');
121:                         $value = max($value, $this->nextMovementNumber());
122:                         DB::statement('ALTER SEQUENCE stock_movement_number_seq RESTART WITH '.$value);
123:                     }
124:                 }
125: 
126:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
127:                     ? ''
128:                     : $this->serializeValue($value, $setting->type);
129:                 $setting->save();
130:             }
131: 
132:             DB::afterCommit(fn () => $this->clearCache());
133:         }, attempts: 3);
134:     }
135: 
136:     /**
137:      * Atomically return and increment the next document number for the requested type.
138:      *
139:      * @throws JsonException
140:      */
141:     public function generateNextNumber(string $type): string
142:     {
143:         if ($type === 'movement') {
144:             [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
145:             $number = DB::selectOne("SELECT nextval('stock_movement_number_seq') AS number")->number;
146: 
147:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
148:         }
149:         $definitions = [
150:             'invoice' => ['prefix' => 'invoice_prefix', 'next' => 'invoice_next_number', 'padding' => 'invoice_padding'],
151:             'order' => ['prefix' => 'order_prefix', 'next' => 'order_next_number', 'padding' => 'order_padding'],
152:             'purchase_order' => ['prefix' => 'purchase_order_prefix', 'next' => 'purchase_order_next_number', 'padding' => 'purchase_order_padding'],
153:             'quotation' => ['prefix' => 'quotation_prefix', 'next' => 'quotation_next_number', 'padding' => 'quotation_padding'],
154:             'transfer' => ['prefix' => 'transfer_prefix', 'next' => 'transfer_next_number', 'padding' => 'transfer_padding'],
155:             'stocktake' => ['prefix' => 'stocktake_prefix', 'next' => 'stocktake_next_number', 'padding' => 'stocktake_padding'],
156:         ];
157: 
158:         if (! isset($definitions[$type])) {
159:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
160:         }
161: 
162:         $definition = $definitions[$type];
163:         [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
164: 
165:         return DB::transaction(function () use ($definition, $prefix, $padding): string {
166:             // العداد وحده يُقفل ويُقرأ طازجًا كل مرة؛ البادئة والحشو من ذاكرة الطلب.
167:             $nextSetting = Setting::query()
168:                 ->where('key', $definition['next'])
169:                 ->lockForUpdate()
170:                 ->first();
171: 
172:             if ($nextSetting === null) {
173:                 throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
174:             }
175: 
176:             $nextValue = $this->counterValue($nextSetting->value);
177: 
178:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
179:             $nextSetting->value = (string) ($nextValue + 1);
180:             $nextSetting->save();
181: 
182:             return $formatted;
183:         }, attempts: 3);
184:     }
185: 
186:     /**
187:      * بادئة وحشو نوع ترقيم — قراءة واحدة لكل طلب بدل استعلام مع كل حركة/مستند.
188:      *
189:      * @return array{0: string, 1: int}
190:      */
191:     private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
192:     {
193:         return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
194:             $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');
195: 
196:             foreach ([$prefixKey, $paddingKey] as $key) {
197:                 if (! $settings->has($key)) {
198:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
199:                 }
200:             }
201: 
202:             return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
203:         })();
204:     }
205: 
206:     public function clearCache(): void
207:     {
208:         Cache::forget(self::CACHE_KEY);
209:         $this->numberingConfig = [];
210:     }
211: 
212:     private function nextMovementNumber(): int
213:     {
214:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
215: 
216:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
217:     }
218: 
219:     private function counterValue(mixed $value): int
220:     {
221:         $number = (is_int($value) || is_string($value))
222:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
223:             : false;
224:         if ($number === false) {
225:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
226:         }
227: 
228:         return $number;
229:     }
230: 
231:     private function castValue(?string $value, string $type): mixed
232:     {
233:         if ($value === null) {
234:             return null;
235:         }
236: 
237:         return match ($type) {
238:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
239:             'integer' => (int) $value,
240:             'float' => (float) $value,
241:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
242:             default => $value,
243:         };
244:     }
245: 
246:     /** @throws JsonException */
247:     private function serializeValue(mixed $value, string $type): ?string
248:     {
249:         if ($value === null) {
250:             return null;
251:         }
252: 
253:         if ($type === 'json') {
254:             return json_encode($value, JSON_THROW_ON_ERROR);
255:         }
256: 
257:         if ($type === 'boolean') {
258:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
259:         }
260: 
261:         return (string) $value;
262:     }
